CREATE OR REPLACE FUNCTION "private"."refresh_and_get_gmail_token"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_integration RECORD;
    v_access_token TEXT;
    v_refresh_token TEXT;
    v_decrypted_response JSONB;
    v_refresh_response JSONB;
    v_supabase_url TEXT;
    v_service_role_key TEXT;
    v_decrypt_function_url TEXT;
    v_refresh_function_url TEXT;
BEGIN
    -- Obtener la integración de Gmail del superadmin
    SELECT * INTO v_integration
    FROM public.tenant_integrations
    WHERE tenant_id = '00000000-0000-0000-0000-000000000000'
      AND provider = 'google_gmail'
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No se encontró la integración de google_gmail para el superadmin.';
    END IF;

    v_access_token := v_integration.access_token;

    -- Lógica de Refresco de Token si es necesario
    IF v_integration.expires_at IS NULL OR v_integration.expires_at < now() THEN
        -- Obtener secretos necesarios
        SELECT decrypted_secret INTO v_supabase_url FROM vault.decrypted_secrets WHERE name = 'supabase_url';
        SELECT decrypted_secret INTO v_service_role_key FROM vault.decrypted_secrets WHERE name = 'supabase_service_role_key';
        
        v_decrypt_function_url := v_supabase_url || '/functions/v1/decrypt-secret';
        v_refresh_function_url := v_supabase_url || '/functions/v1/refresh-google-token';

        -- 1. Descifrar el refresh token llamando a la Edge Function segura
        SELECT content INTO v_decrypted_response FROM net.http_post(
            url:= v_decrypt_function_url,
            body:= jsonb_build_object(
                'encryptedData', v_integration.encrypted_credentials,
                'iv', v_integration.nonce
            ),
            headers:= jsonb_build_object(
                'Content-Type', 'application/json',
                'Authorization', 'Bearer ' || v_service_role_key
            )
        );

        IF v_decrypted_response->>'decryptedText' IS NULL THEN
            RAISE EXCEPTION 'Error al descifrar el token desde Edge Function: %', (v_decrypted_response->>'error');
        END IF;
        v_refresh_token := v_decrypted_response->>'decryptedText';

        -- 2. Invocar la Edge Function para obtener un nuevo token de acceso
        SELECT content INTO v_refresh_response FROM net.http_post(
            url:= v_refresh_function_url,
            body:= jsonb_build_object('refreshToken', v_refresh_token),
            headers:= jsonb_build_object(
                'Content-Type', 'application/json',
                'Authorization', 'Bearer ' || v_service_role_key
            )
        );
        
        IF v_refresh_response->>'access_token' IS NULL THEN
            RAISE EXCEPTION 'Error al refrescar token desde Edge Function: %', (v_refresh_response->>'error');
        END IF;

        v_access_token := v_refresh_response->>'access_token';

        -- 3. Actualizar la tabla con el nuevo token y la nueva fecha de expiración
        UPDATE public.tenant_integrations
        SET
            access_token = v_access_token,
            expires_at = now() + ((v_refresh_response->>'expires_in')::INT * interval '1 second')
        WHERE id = v_integration.id;
    END IF;

    RETURN v_access_token;
END;
$$;


ALTER FUNCTION "private"."refresh_and_get_gmail_token"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."send_email_via_gmail_api"("p_recipient_email" "text", "p_subject" "text", "p_body_html" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_integration RECORD;
    v_access_token TEXT;
    v_refresh_token TEXT;
    v_encryption_key TEXT;
    v_google_client_id TEXT;
    v_google_client_secret TEXT;
    v_request_id BIGINT;
    v_response RECORD;
    v_response_body JSONB;
    v_mime_message TEXT;
    v_base64_mime TEXT;
    v_request_body JSONB;
BEGIN
    -- AUMENTAR EL TIMEOUT PARA ESTA TRANSACCIÓN
    SET statement_timeout = '30s';

    -- Obtener la integración de Gmail del superadmin
    SELECT * INTO v_integration
    FROM public.tenant_integrations
    WHERE tenant_id = '00000000-0000-0000-0000-000000000000'
      AND provider = 'google_gmail'
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'No se encontró la integración de google_gmail para el superadmin.');
    END IF;

    v_access_token := v_integration.access_token;

    -- Lógica de Refresco de Token si es necesario
    IF v_integration.expires_at IS NULL OR v_integration.expires_at < now() THEN
        -- Obtener secretos
        SELECT decrypted_secret INTO v_google_client_id FROM vault.decrypted_secrets WHERE name = 'google_client_id';
        SELECT decrypted_secret INTO v_google_client_secret FROM vault.decrypted_secrets WHERE name = 'google_client_secret';
        SELECT decrypted_secret INTO v_encryption_key FROM vault.decrypted_secrets WHERE name = 'glamtica_encryption_key';

        -- Desencriptar el refresh token
        v_refresh_token := pgp_sym_decrypt(v_integration.encrypted_refresh_token, v_encryption_key);

        -- Enviar la solicitud de refresco
        v_request_id := net.http_post(
            url:= 'https://oauth2.googleapis.com/token',
            body:= jsonb_build_object(
                'client_id', v_google_client_id,
                'client_secret', v_google_client_secret,
                'refresh_token', v_refresh_token,
                'grant_type', 'refresh_token'
            ),
            headers:= '{"Content-Type": "application/json"}'::jsonb
        );

        -- Esperar y recoger la respuesta
        SELECT * INTO v_response FROM net.http_collect_response(v_request_id, async:=false);
        v_response_body := v_response.body::jsonb;

        IF v_response.status_code != 200 THEN
            RETURN jsonb_build_object('success', false, 'error', 'Error al refrescar token: ' || (v_response_body->>'error_description'));
        END IF;

        v_access_token := v_response_body->>'access_token';

        -- Actualizar la tabla con el nuevo token
        UPDATE public.tenant_integrations
        SET
            access_token = v_access_token,
            expires_at = now() + ((v_response_body->>'expires_in')::INT * interval '1 second')
        WHERE id = v_integration.id;
    END IF;

    -- Construir y enviar el correo
    v_mime_message := 'From: ' || v_integration.account_email || E'\r\n' ||
                      'To: ' || p_recipient_email || E'\r\n' ||
                      'Subject: ' || p_subject || E'\r\n' ||
                      'Content-Type: text/html; charset=UTF-8' || E'\r\n\r\n' ||
                      p_body_html;

    v_base64_mime := encode(convert_to(v_mime_message, 'UTF8'), 'base64');
    v_request_body := jsonb_build_object('raw', v_base64_mime);

    v_request_id := net.http_post(
        url:= 'https://gmail.googleapis.com/gmail/v1/users/me/messages/send',
        body:= v_request_body,
        headers:= jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_access_token
        )
    );
    
    SELECT * INTO v_response FROM net.http_collect_response(v_request_id, async:=false);
    v_response_body := v_response.body::jsonb;

    IF v_response.status_code = 200 AND v_response_body ? 'id' THEN
        RETURN jsonb_build_object('success', true);
    ELSE
        RETURN jsonb_build_object('success', false, 'error', 'Error en la API de Gmail: ' || (v_response_body->'error'->>'message'));
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'error', 'Excepción en send_email_via_gmail_api: ' || SQLERRM);
END;
$$;


ALTER FUNCTION "private"."send_email_via_gmail_api"("p_recipient_email" "text", "p_subject" "text", "p_body_html" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_branches_batch"("p_tenant_id" "uuid", "p_branch_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_branch_id UUID;
    v_branch RECORD;
    v_subscription RECORD;
    v_price_history RECORD;
    v_subscription_status TEXT;
    v_days_in_cycle INT;
    v_days_remaining INT;
    v_daily_rate NUMERIC;
    v_prorated_amount NUMERIC;
    v_branch_price NUMERIC;
    
    v_activated_count INT := 0;
    v_failed_count INT := 0;
    v_total_prorated_amount NUMERIC := 0;
    v_details JSONB[] := ARRAY[]::JSONB[];
    v_error_message TEXT;
BEGIN
    -- Step 1: Verify the tenant has an active subscription once
    SELECT status INTO v_subscription_status FROM public.get_tenant_subscription_status(p_tenant_id);
    IF v_subscription_status != 'activo' THEN
        RETURN jsonb_build_object(
            'success', false, 
            'message', 'Cannot activate branches. Tenant subscription status is: ' || v_subscription_status,
            'activated_count', 0,
            'failed_count', array_length(p_branch_ids, 1),
            'total_prorated_amount', 0,
            'details', '[]'::JSONB
        );
    END IF;

    -- Step 2: Get the latest subscription record once
    SELECT * INTO v_subscription 
    FROM public.tenant_subscriptions 
    WHERE tenant_id = p_tenant_id 
    ORDER BY end_date DESC NULLS FIRST 
    LIMIT 1;
    
    IF v_subscription IS NULL THEN 
        RETURN jsonb_build_object(
            'success', false, 
            'message', 'No active subscription record found for the tenant.',
            'activated_count', 0,
            'failed_count', array_length(p_branch_ids, 1),
            'total_prorated_amount', 0,
            'details', '[]'::JSONB
        );
    END IF;

    -- Step 3: Loop through each branch ID
    FOREACH v_branch_id IN ARRAY p_branch_ids
    LOOP
        BEGIN
            -- Step 3a: Validate the branch
            SELECT * INTO v_branch FROM public.branches WHERE id = v_branch_id AND tenant_id = p_tenant_id;
            IF v_branch IS NULL THEN RAISE EXCEPTION 'Branch not found or access denied'; END IF;
            IF v_branch.status <> 'pending_activation' THEN RAISE EXCEPTION 'Branch is not pending activation'; END IF;

            -- Step 3b: Get the price for the plan
            SELECT extra_branch_price_cop INTO v_branch_price
            FROM public.plan_price_history
            WHERE subscription_plan_id = v_subscription.subscription_plan_id AND effective_date <= NOW()
            ORDER BY effective_date DESC
            LIMIT 1;

            IF v_branch_price IS NULL OR v_branch_price <= 0 THEN 
                RAISE EXCEPTION 'Could not find a valid price for the branch.'; 
            END IF;

            -- Step 3c: Proration Calculation
            IF v_subscription.end_date IS NULL THEN
                RAISE EXCEPTION 'The current subscription has no end date.';
            ELSE
                v_days_in_cycle := v_subscription.end_date::date - v_subscription.start_date::date;
                v_days_remaining := v_subscription.end_date::date - NOW()::date;
                v_prorated_amount := 0;
                IF v_days_remaining > 0 AND v_days_in_cycle > 0 THEN
                    v_daily_rate := v_branch_price / v_days_in_cycle;
                    v_prorated_amount := v_daily_rate * v_days_remaining;
                END IF;
            END IF;

            -- Step 3d: Activate the branch and create the asset
            UPDATE public.branches SET status = 'active', activated_at = NOW() WHERE id = v_branch_id;
            INSERT INTO public.subscription_assets (tenant_subscription_id, asset_type, asset_reference_id, status, price_at_addition)
            VALUES (v_subscription.id, 'branch', v_branch_id, 'active', v_branch_price);

            -- Step 3e: Log success
            v_activated_count := v_activated_count + 1;
            v_total_prorated_amount := v_total_prorated_amount + round(v_prorated_amount, 2);
            v_details := array_append(v_details, jsonb_build_object(
                'branch_id', v_branch_id, 
                'status', 'success', 
                'amount_charged', round(v_prorated_amount, 2)
            ));

        EXCEPTION
            WHEN OTHERS THEN
                GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
                v_failed_count := v_failed_count + 1;
                v_details := array_append(v_details, jsonb_build_object(
                    'branch_id', v_branch_id, 
                    'status', 'failed', 
                    'error', v_error_message
                ));
        END;
    END LOOP;

    -- Step 4: Return the consolidated result
    RETURN jsonb_build_object(
        'success', v_failed_count = 0,
        'activated_count', v_activated_count,
        'failed_count', v_failed_count,
        'total_prorated_amount', v_total_prorated_amount,
        'details', to_jsonb(v_details)
    );
END;
$$;


ALTER FUNCTION "public"."activate_branches_batch"("p_tenant_id" "uuid", "p_branch_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."activate_branches_batch"("p_tenant_id" "uuid", "p_branch_ids" "uuid"[]) IS 'Activates a batch of branches, calculates prorated charges, and creates corresponding subscription assets.';



CREATE OR REPLACE FUNCTION "public"."activate_subscription"("p_tenant_id" "uuid", "p_plan_price_id" "uuid", "p_payment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_plan_id UUID;
    v_tenant_country_id UUID;
    v_pcc_id UUID;
    v_billing_frequency_months INT;
    v_previous_end_date TIMESTAMPTZ;
    v_new_end_date TIMESTAMPTZ;
    v_new_start_date TIMESTAMPTZ;
BEGIN
    -- Steps 1-4: Get plan, country, and configuration info
    SELECT subscription_plan_id INTO v_plan_id
    FROM public.price_tariffs WHERE id = p_plan_price_id;
    IF v_plan_id IS NULL THEN RAISE EXCEPTION 'Plan not found for price_id: %', p_plan_price_id; END IF;

    SELECT country_id INTO v_tenant_country_id
    FROM public.tenants WHERE id = p_tenant_id;
    IF v_tenant_country_id IS NULL THEN RAISE EXCEPTION 'Country not found for tenant: %', p_tenant_id; END IF;

    SELECT id INTO v_pcc_id
    FROM public.plan_country_configurations WHERE plan_id = v_plan_id AND country_id = v_tenant_country_id;
    IF v_pcc_id IS NULL THEN RAISE EXCEPTION 'Plan configuration not found for plan % in country %', v_plan_id, v_tenant_country_id; END IF;

    SELECT billing_frequency_months INTO v_billing_frequency_months
    FROM public.subscription_plans WHERE id = v_plan_id;
    IF v_billing_frequency_months IS NULL THEN RAISE EXCEPTION 'Billing frequency not found for plan %', v_plan_id; END IF;

    -- 5. Find the end_date of the single ACTIVE subscription
    SELECT end_date INTO v_previous_end_date
    FROM public.tenant_subscriptions
    WHERE tenant_id = p_tenant_id AND is_active = true
    LIMIT 1;

    -- 6. Calculate new dates. FOUND is a special variable that is true if the last SELECT INTO found a row.
    IF FOUND AND NOW() <= (v_previous_end_date + '5 days'::interval) THEN
        -- If an active subscription was found and it's still valid (or in grace period)
        v_new_start_date := v_previous_end_date;
        v_new_end_date := v_previous_end_date + (v_billing_frequency_months || ' months')::interval;
    ELSE
        -- If no active sub was found (FOUND is false) or it's long expired
        v_new_start_date := NOW();
        v_new_end_date := NOW() + (v_billing_frequency_months || ' months')::interval;
    END IF;

    -- 7. Deactivate all old subscriptions for the tenant
    UPDATE public.tenant_subscriptions
    SET is_active = false
    WHERE tenant_id = p_tenant_id AND is_active = true;

    -- 8. Insert the new subscription record
    INSERT INTO public.tenant_subscriptions (
        tenant_id,
        plan_country_configuration_id,
        is_active,
        start_date,
        end_date,
        is_trial
    )
    VALUES (
        p_tenant_id,
        v_pcc_id,
        true,
        v_new_start_date,
        v_new_end_date,
        FALSE
    );

END;
$$;


ALTER FUNCTION "public"."activate_subscription"("p_tenant_id" "uuid", "p_plan_price_id" "uuid", "p_payment_id" "uuid") OWNER TO "postgres";

