CREATE OR REPLACE FUNCTION "public"."cancel_attention_and_notify"("p_attention_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_attention RECORD;
BEGIN
    -- Step 1: Get attention details for the notification
    SELECT tenant_id, client_id INTO v_attention FROM public.attentions WHERE id = p_attention_id;

    IF v_attention IS NULL THEN
        RAISE EXCEPTION 'Attention with ID % not found.', p_attention_id;
    END IF;

    -- Step 2: Update the attention status
    UPDATE public.attentions
    SET status = 'Cancelada'
    WHERE id = p_attention_id;

    -- Step 3: Enqueue client notifications for the cancellation
    BEGIN
        -- Email Notification
        PERFORM public.queue_client_email(
            p_tenant_id := v_attention.tenant_id,
            p_client_id := v_attention.client_id,
            p_template_type := 'attention_cancelled',
            p_template_data := '{}'::jsonb
        );
    EXCEPTION
        WHEN others THEN
            RAISE WARNING 'Failed to queue client cancellation email for attention_id %: %', p_attention_id, SQLERRM;
    END;

    BEGIN
        -- WhatsApp Notification
        PERFORM public.queue_client_whatsapp(
            p_tenant_id := v_attention.tenant_id,
            p_client_id := v_attention.client_id,
            p_template_name := 'attention_cancelled_whatsapp',
            p_template_params := '{}'::jsonb
        );
    EXCEPTION
        WHEN others THEN
            RAISE WARNING 'Failed to queue client cancellation WhatsApp for attention_id %: %', p_attention_id, SQLERRM;
    END;

END;
$$;


ALTER FUNCTION "public"."cancel_attention_and_notify"("p_attention_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_attention_and_notify"("p_attention_id" "uuid") IS 'V2: Cancels an attention and queues both email and WhatsApp notifications for the client.';



CREATE OR REPLACE FUNCTION "public"."cancel_product_transfer"("p_transfer_id" "uuid", "p_tenant_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    updated_transfer record;
    v_transfer_status text;
    v_origin_branch_id uuid;
    v_destination_branch_id uuid;
    v_user_can_cancel boolean;
BEGIN
    -- 1. Get transfer details
    SELECT status, origin_branch_id, destination_branch_id
    INTO v_transfer_status, v_origin_branch_id, v_destination_branch_id
    FROM public.product_transfers
    WHERE id = p_transfer_id AND tenant_id = p_tenant_id;

    IF v_transfer_status IS NULL THEN
        RAISE EXCEPTION 'Transfer not found or you do not have permission.';
    END IF;

    -- 2. Check permissions
    v_user_can_cancel := false;
    IF v_transfer_status = 'solicitado' THEN
        SELECT EXISTS (
            SELECT 1
            FROM auth.users u,
                 jsonb_array_elements(u.raw_app_meta_data->'assignments') as assignment
            WHERE u.id = p_user_id
              AND (assignment->>'branch_id' = v_origin_branch_id::text OR assignment->>'branch_id' = v_destination_branch_id::text)
              AND assignment->>'tenant_id' = p_tenant_id::text
        ) INTO v_user_can_cancel;
    ELSIF v_transfer_status = 'aprobado' THEN
        SELECT EXISTS (
            SELECT 1
            FROM auth.users u,
                 jsonb_array_elements(u.raw_app_meta_data->'assignments') as assignment
            WHERE u.id = p_user_id
              AND assignment->>'branch_id' = v_origin_branch_id::text
              AND assignment->>'tenant_id' = p_tenant_id::text
        ) INTO v_user_can_cancel;
    END IF;

    IF NOT v_user_can_cancel THEN
        RAISE EXCEPTION 'You do not have permission to cancel this transfer in its current state.';
    END IF;

    -- 3. Update the transfer status to 'cancelado'
    UPDATE public.product_transfers
    SET status = 'cancelado', updated_at = now()
    WHERE id = p_transfer_id
    RETURNING * INTO updated_transfer;

    RETURN to_jsonb(updated_transfer);
END;
$$;


