CREATE OR REPLACE FUNCTION "public"."change_password"("p_user_id" "uuid", "p_current_password" "text", "p_new_password" "text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_user auth.users;
    v_password_matches BOOLEAN;
BEGIN
    -- 1. Verificar que el usuario exista
    SELECT * INTO v_user
    FROM auth.users u
    WHERE u.id = p_user_id;

    IF v_user.id IS NULL THEN
        RETURN QUERY SELECT FALSE, 'Usuario no encontrado.';
        RETURN;
    END IF;

    -- 2. Verificar que la contraseña actual sea correcta
    SELECT u.encrypted_password = crypt(p_current_password, u.encrypted_password) INTO v_password_matches
    FROM auth.users u WHERE u.id = p_user_id;

    IF NOT v_password_matches THEN
        RETURN QUERY SELECT FALSE, 'La contraseña actual es incorrecta.';
        RETURN;
    END IF;

    -- 3. Actualizar con la nueva contraseña
    UPDATE auth.users
    SET encrypted_password = crypt(p_new_password, gen_salt('bf'))
    WHERE id = p_user_id;

    -- 4. Devolver éxito
    RETURN QUERY SELECT TRUE, 'Contraseña actualizada exitosamente.';

EXCEPTION
    WHEN OTHERS THEN
        RETURN QUERY SELECT FALSE, 'Ocurrió un error inesperado al cambiar la contraseña.';
END;
$$;


ALTER FUNCTION "public"."change_password"("p_user_id" "uuid", "p_current_password" "text", "p_new_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_asset_limit"("p_tenant_id" "uuid", "p_asset_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_limit INT;
    v_current_count INT;
    v_plan_id UUID;
    v_asset_id UUID;
BEGIN
    -- Step 1: Find the tenant's active subscription plan
    SELECT active_plan_id INTO v_plan_id
    FROM public.tenant_subscriptions
    WHERE tenant_id = p_tenant_id
    AND status = 'active'
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_plan_id IS NULL THEN
        -- No active plan found, default to allowing the action
        RETURN TRUE;
    END IF;

    -- Step 2: Find the asset_id from the asset_key
    SELECT id INTO v_asset_id
    FROM public.plan_assets
    WHERE asset_key = p_asset_key
    -- This assumes asset_key is unique across platforms, or we need platform_id
    LIMIT 1;

    IF v_asset_id IS NULL THEN
        -- The asset type doesn't exist, so no limit is enforced
        RETURN TRUE;
    END IF;

    -- Step 3: Find the limit value for the plan and asset
    SELECT value::INT INTO v_limit
    FROM public.plan_asset_limits
    WHERE plan_id = v_plan_id AND asset_id = v_asset_id;

    IF v_limit IS NULL THEN
        -- No specific limit set for this asset in this plan, allow action
        RETURN TRUE;
    END IF;

    -- Step 4: Count the current number of resources based on the asset_key
    IF p_asset_key = 'max_branches' THEN
        SELECT COUNT(*)::INT INTO v_current_count
        FROM public.branches
        WHERE tenant_id = p_tenant_id;
    -- Add other cases here in the future
    -- ELSIF p_asset_key = 'max_users' THEN
    --     SELECT COUNT(*)::INT INTO v_current_count ...
    ELSE
        -- If the asset key is unknown, we don't enforce a limit
        RETURN TRUE;
    END IF;

    -- Step 5: Compare current count with the limit
    RETURN v_current_count < v_limit;
END;
$$;


ALTER FUNCTION "public"."check_asset_limit"("p_tenant_id" "uuid", "p_asset_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_slug_availability"("params" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    p_slug text := params->>'p_slug';
    p_country_id uuid := (params->>'p_country_id')::uuid;
    p_tenant_id uuid := (params->>'p_tenant_id')::uuid;
    p_platform_id uuid;
BEGIN
    -- Get platform_id from the tenant
    SELECT platform_id INTO p_platform_id FROM public.tenants WHERE id = p_tenant_id;
    IF p_platform_id IS NULL THEN
        RAISE EXCEPTION 'Could not determine platform for tenant';
    END IF;

    RETURN NOT EXISTS (
        SELECT 1
        FROM public.tenants
        WHERE slug = p_slug 
          AND country_id = p_country_id
          AND platform_id = p_platform_id
          AND id != p_tenant_id
    );
END;
$$;


