CREATE OR REPLACE FUNCTION "public"."create_daily_dummy_attentions"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    glamtica_tenant_id UUID := (SELECT id FROM tenants WHERE platform_id = (SELECT id FROM platforms WHERE name = 'Glamtica') AND is_system_owner = true LIMIT 1);
    tattoosuite_tenant_id UUID := (SELECT id FROM tenants WHERE platform_id = (SELECT id FROM platforms WHERE name = 'Tattoo Suite') AND is_system_owner = true LIMIT 1);
    selected_tenant_id UUID;
    selected_client_id UUID;
    selected_service_id UUID;
    selected_user_id UUID;
    selected_branch_id UUID;
    new_attention_id UUID;
    service_price NUMERIC;
    service_duration INT;
    attention_count INT;
BEGIN
    -- Decidir aleatoriamente cuántas atenciones crear (entre 5 y 15)
    attention_count := floor(random() * 11) + 5;

    FOR i IN 1..attention_count LOOP
        -- 1. Seleccionar un tenant aleatoriamente
        IF random() < 0.5 THEN
            selected_tenant_id := glamtica_tenant_id;
        ELSE
            selected_tenant_id := tattoosuite_tenant_id;
        END IF;

        -- 2. Seleccionar un cliente, servicio, usuario y sucursal aleatorios de ese tenant
        SELECT id INTO selected_client_id FROM clients WHERE tenant_id = selected_tenant_id ORDER BY random() LIMIT 1;
        SELECT id, selling_price, duration_minutes, branch_id INTO selected_service_id, service_price, service_duration, selected_branch_id FROM branch_services WHERE tenant_id = selected_tenant_id ORDER BY random() LIMIT 1;
        SELECT user_id INTO selected_user_id FROM user_assignments WHERE tenant_id = selected_tenant_id AND branch_id = selected_branch_id ORDER BY random() LIMIT 1;

        -- Asegurarse de que no se seleccionaron valores nulos que rompan la inserción
        IF selected_client_id IS NULL OR selected_service_id IS NULL OR selected_user_id IS NULL OR selected_branch_id IS NULL THEN
            RAISE WARNING 'No se pudieron obtener datos suficientes para crear una atención para el tenant: %', selected_tenant_id;
            CONTINUE; -- Saltar a la siguiente iteración del bucle
        END IF;

        -- 3. Crear la atención principal
        INSERT INTO public.attentions (tenant_id, branch_id, client_id, status, total_amount, attention_datetime)
        VALUES (selected_tenant_id, selected_branch_id, selected_client_id, 'Pagada', service_price, NOW() - (floor(random() * 30) || ' days')::interval)
        RETURNING id INTO new_attention_id;

        -- 4. Crear el servicio asociado a la atención
        INSERT INTO public.attention_services (attention_id, service_id, user_id, service_price, status, tenant_id, branch_id, duration_minutes)
        VALUES (new_attention_id, selected_service_id, selected_user_id, service_price, 'Finalizado', selected_tenant_id, selected_branch_id, service_duration);

    END LOOP;
END;
$$;


ALTER FUNCTION "public"."create_daily_dummy_attentions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_equipment"("p_equipment_data" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    new_equipment_id uuid;
BEGIN
    INSERT INTO equipment (tenant_id, name, type_id, brand_id, model, serial_number, purchase_date, last_maintenance_date, maintenance_frequency, maintenance_frequency_unit, notes, is_active)
    VALUES (
        (p_equipment_data->>'tenant_id')::uuid,
        p_equipment_data->>'name',
        (p_equipment_data->>'type_id')::uuid,
        NULLIF(p_equipment_data->>'brand_id', '')::uuid, -- Solución: Previene error si la marca es opcional
        p_equipment_data->>'model',
        p_equipment_data->>'serial_number',
        NULLIF(p_equipment_data->>'purchase_date', '')::date, -- Solución: Previene error con fechas vacías
        NULLIF(p_equipment_data->>'last_maintenance_date', '')::date, -- Solución: Previene error con fechas vacías
        (p_equipment_data->>'maintenance_frequency')::integer,
        p_equipment_data->>'maintenance_frequency_unit',
        p_equipment_data->>'notes',
        (p_equipment_data->>'is_active')::boolean -- Solución: Añadido para guardar el estado del toggle
    ) RETURNING id INTO new_equipment_id;
    RETURN new_equipment_id;
END;
$$;


ALTER FUNCTION "public"."create_equipment"("p_equipment_data" "jsonb") OWNER TO "postgres";


