CREATE OR REPLACE FUNCTION "public"."create_product_movement"("p_tenant_id" "uuid", "p_branch_id" "uuid", "p_product_id" "uuid", "p_movement_type" "text", "p_quantity_change" numeric, "p_cost_of_change" numeric, "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_reference_type" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    branch_product_rec RECORD;
    new_stock numeric;
    new_avg_cost numeric;
BEGIN
    -- Lock the specific branch_product row to prevent race conditions on stock updates
    SELECT *
    INTO branch_product_rec
    FROM public.branch_products
    WHERE branch_id = p_branch_id AND product_id = p_product_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product % not found in branch %', p_product_id, p_branch_id;
    END IF;

    -- Calculate new stock
    new_stock := branch_product_rec.stock_quantity + p_quantity_change;

    -- Calculate new weighted average cost
    -- Avoid division by zero if the new stock is zero
    IF new_stock > 0 THEN
        -- (Current total value + Value of change) / New total quantity
        new_avg_cost := ((branch_product_rec.stock_quantity * branch_product_rec.cost_price) + (p_quantity_change * p_cost_of_change)) / new_stock;
    ELSE
        -- If stock is zero, the cost should also be zero.
        new_avg_cost := 0;
    END IF;

    -- Update the branch_products table with the new stock and cost
    UPDATE public.branch_products
    SET
        stock_quantity = new_stock,
        cost_price = new_avg_cost
    WHERE id = branch_product_rec.id;

    -- Insert the movement record with the snapshot values
    INSERT INTO public.product_movements (
        tenant_id,
        branch_id,
        product_id,
        movement_date,
        movement_type,
        quantity_change,
        cost_of_change,
        stock_after_movement,
        cost_after_movement,
        reference_id,
        reference_type
    ) VALUES (
        p_tenant_id,
        p_branch_id,
        p_product_id,
        now(),
        p_movement_type,
        p_quantity_change,
        p_cost_of_change,
        new_stock,
        new_avg_cost,
        p_reference_id,
        p_reference_type
    );

END;
$$;


ALTER FUNCTION "public"."create_product_movement"("p_tenant_id" "uuid", "p_branch_id" "uuid", "p_product_id" "uuid", "p_movement_type" "text", "p_quantity_change" numeric, "p_cost_of_change" numeric, "p_reference_id" "uuid", "p_reference_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_product_movement"("p_tenant_id" "uuid", "p_branch_id" "uuid", "p_product_id" "uuid", "p_movement_type" "text", "p_quantity_change" numeric, "p_cost_of_change" numeric, "p_reference_id" "uuid", "p_reference_type" "text") IS 'Records a product movement, updates the stock and weighted average cost for the product in the branch.';



CREATE OR REPLACE FUNCTION "public"."create_product_transfer"("p_tenant_id" "uuid", "p_from_branch_id" "uuid", "p_to_branch_id" "uuid", "p_transfer_date" timestamp with time zone, "p_notes" "text", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_transfer_id UUID;
    item RECORD; -- Usamos un RECORD genérico para iterar
BEGIN
    -- 1. Crear el registro principal de la transferencia
    INSERT INTO product_transfers (tenant_id, from_branch_id, to_branch_id, transfer_date, status, notes)
    VALUES (p_tenant_id, p_from_branch_id, p_to_branch_id, p_transfer_date, 'en_proceso', p_notes)
    RETURNING id INTO v_transfer_id;

    -- 2. Insertar los items y actualizar el stock de origen usando jsonb_to_recordset
    FOR item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(product_id UUID, quantity INT)
    LOOP
        -- Insertar el item en la tabla de detalles
        INSERT INTO product_transfer_items (transfer_id, product_id, quantity)
        VALUES (v_transfer_id, item.product_id, item.quantity);

        -- Actualizar (restar) el stock en la sucursal de origen
        UPDATE branch_products
        SET stock_quantity = stock_quantity - item.quantity
        WHERE branch_id = p_from_branch_id AND product_id = item.product_id;
    END LOOP;

    -- 4. Devolver el ID de la transferencia creada
    RETURN v_transfer_id;
END;
$$;


ALTER FUNCTION "public"."create_product_transfer"("p_tenant_id" "uuid", "p_from_branch_id" "uuid", "p_to_branch_id" "uuid", "p_transfer_date" timestamp with time zone, "p_notes" "text", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_product_transfer_request"("p_tenant_id" "uuid", "p_requesting_branch_id" "uuid", "p_origin_branch_id" "uuid", "p_notes" "text", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    new_transfer record;
    item jsonb;
BEGIN
    -- 1. Create the product_transfers record
    INSERT INTO public.product_transfers (
        tenant_id,
        requesting_branch_id,
        origin_branch_id,
        destination_branch_id,
        status,
        notes,
        transfer_date
    )
    VALUES (
        p_tenant_id,
        p_requesting_branch_id,
        p_origin_branch_id,
        p_requesting_branch_id, -- Destination is the same as the requesting branch
        'solicitado',
        p_notes,
        now()
    )
    RETURNING * INTO new_transfer;

    -- 2. Create product_transfer_items records
    FOR item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        INSERT INTO public.product_transfer_items (
            transfer_id,
            product_id,
            quantity
        )
        VALUES (
            new_transfer.id,
            (item->>'product_id')::uuid,
            (item->>'quantity')::integer
        );
    END LOOP;

    -- 3. Return the newly created transfer
    RETURN to_jsonb(new_transfer);
END;
$$;


ALTER FUNCTION "public"."create_product_transfer_request"("p_tenant_id" "uuid", "p_requesting_branch_id" "uuid", "p_origin_branch_id" "uuid", "p_notes" "text", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_recovery_link"("p_user_email" "text", "p_user_role" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  response JSON;
  request_id BIGINT;
  project_url TEXT;
  service_role_key TEXT;
BEGIN
  RAISE NOTICE '[create_recovery_link] Starting for email: %', p_user_email;

  IF p_user_role != 'super_admin' THEN
    RAISE EXCEPTION 'Access denied. Super admin role required.';
  END IF;

  SELECT decrypted_secret INTO project_url FROM vault.decrypted_secrets WHERE name = 'SUPABASE_URL';
  SELECT decrypted_secret INTO service_role_key FROM vault.decrypted_secrets WHERE name = 'SUPABASE_SERVICE_ROLE_KEY';
  RAISE NOTICE '[create_recovery_link] Project URL from vault: %', project_url;
  RAISE NOTICE '[create_recovery_link] Service Role Key from vault (is null?): %', service_role_key IS NULL;

  IF project_url IS NULL OR service_role_key IS NULL THEN
      RAISE EXCEPTION 'URL or Service Role Key not configured in Vault.';
  END IF;

  SELECT
      id
  INTO
      request_id
  FROM
      net.http_post(
          url := project_url || '/auth/v1/admin/generate_link',
          headers := jsonb_build_object(
              'apikey', service_role_key,
              'Authorization', 'Bearer ' || service_role_key,
              'Content-Type', 'application/json'
          ),
          body := jsonb_build_object(
              'type', 'recovery',
              'email', p_user_email
          )
      );
  RAISE NOTICE '[create_recovery_link] HTTP request sent. Request ID: %', request_id;

  SELECT
      content::json
  INTO
      response
  FROM
      net.http_collect_response(request_id, timeout_milliseconds := 2000);
  RAISE NOTICE '[create_recovery_link] HTTP response received: %', response;

  RETURN json_build_object('recoveryLink', response -> 'action_link');

END;
$$;


ALTER FUNCTION "public"."create_recovery_link"("p_user_email" "text", "p_user_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_signed_avatar_upload_url"("p_file_path" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    signed_url TEXT;
BEGIN
    -- Generate a signed URL that is valid for 5 minutes.
    -- The URL allows uploading a file with the specified path.
    SELECT storage.sign_upload_url('avatars', p_file_path, 300) INTO signed_url;

    RETURN json_build_object('success', TRUE, 'signedUrl', signed_url);
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to create signed upload URL: %', SQLERRM;
END;
$$;


ALTER FUNCTION "public"."create_signed_avatar_upload_url"("p_file_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tenant"("tenant_name" "text", "tenant_contact_person" "text", "tenant_contact_email" "text", "tenant_contact_phone" "text", "tenant_address" "text", "tenant_city" "text", "tenant_country_id" "uuid", "tenant_logo_url" "text", "tenant_notes" "text", "admin_email" "text", "admin_password" "text", "admin_language_code" "text", "admin_currency_id" "uuid", "admin_timezone" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    new_tenant_id UUID;
    tenant_super_admin_role_id UUID;
    new_branch_id UUID;
BEGIN
    -- Get the role_id for 'tenant_super_admin'
    SELECT id INTO tenant_super_admin_role_id FROM public.roles WHERE name = 'tenant_super_admin';

    IF tenant_super_admin_role_id IS NULL THEN
        RAISE EXCEPTION 'Role "tenant_super_admin" not found.';
    END IF;

    -- Insert new tenant
    INSERT INTO public.tenants (
        name,
        contact_person,
        contact_email,
        contact_phone,
        address,
        city,
        country_id,
        logo_url,
        notes,
        default_language_code,
        default_currency_id,
        default_timezone
    )
    VALUES (
        tenant_name,
        tenant_contact_person,
        tenant_contact_email,
        tenant_contact_phone,
        tenant_address,
        tenant_city,
        tenant_country_id,
        tenant_logo_url,
        tenant_notes,
        admin_language_code,
        admin_currency_id,
        admin_timezone
    )
    RETURNING id INTO new_tenant_id;

    -- Create a default branch for the new tenant
    INSERT INTO public.branches (
        tenant_id,
        name,
        address,
        language_code,
        currency_id,
        timezone
    )
    VALUES (
        new_tenant_id,
        'Sede Principal', -- Default branch name
        tenant_address,
        admin_language_code,
        admin_currency_id,
        admin_timezone
    )
    RETURNING id INTO new_branch_id;

    -- Create the tenant_super_admin user
    INSERT INTO public.users (
        email,
        password_hash,
        role_id,
        tenant_id,
        branch_id,
        language_code,
        currency_id,
        timezone,
        is_active
    )
    VALUES (
        admin_email,
        crypt(admin_password, gen_salt('bf')), -- Hash the password
        tenant_super_admin_role_id,
        new_tenant_id,
        new_branch_id,
        admin_language_code,
        admin_currency_id,
        admin_timezone,
        TRUE
    );

    RETURN new_tenant_id;
END;
$$;


ALTER FUNCTION "public"."create_tenant"("tenant_name" "text", "tenant_contact_person" "text", "tenant_contact_email" "text", "tenant_contact_phone" "text", "tenant_address" "text", "tenant_city" "text", "tenant_country_id" "uuid", "tenant_logo_url" "text", "tenant_notes" "text", "admin_email" "text", "admin_password" "text", "admin_language_code" "text", "admin_currency_id" "uuid", "admin_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tenant_and_admin_logic"("p_business_name" "text", "p_country_id" "uuid", "p_default_language_code" "text", "p_default_currency_id" "uuid", "p_default_timezone" "text", "p_contact_phone" "text", "p_whatsapp_phone" "text", "p_commercial_email" "text", "p_legal_name" "text", "p_tax_id" "text", "p_billing_address" "text", "p_einvoicing_email" "text", "p_physical_address_line1" "text", "p_physical_address_line2" "text", "p_physical_city" "text", "p_physical_state" "text", "p_physical_postal_code" "text", "p_website" "text", "p_latitude" numeric, "p_longitude" numeric, "p_admin_email" "text", "p_admin_password" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    new_tenant_id UUID;
    new_user_id UUID;
    new_branch_id UUID;
BEGIN
    -- 1. Crear el Tenant
    INSERT INTO tenants (
        name, country_id, default_language_code, default_currency_id, default_timezone,
        contact_phone, whatsapp_phone, commercial_email, legal_name, tax_id,
        billing_address, einvoicing_email, physical_address_line1, physical_address_line2,
        physical_city, physical_state, physical_postal_code, website, latitude, longitude,
        subscription_status
    ) VALUES (
        p_business_name, p_country_id, p_default_language_code, p_default_currency_id, p_default_timezone,
        p_contact_phone, p_whatsapp_phone, p_commercial_email, p_legal_name, p_tax_id,
        p_billing_address, p_einvoicing_email, p_physical_address_line1, p_physical_address_line2,
        p_physical_city, p_physical_state, p_physical_postal_code, p_website, p_latitude, p_longitude,
        'trial' -- Todos los registros nuevos comienzan en 'trial'
    ) RETURNING id INTO new_tenant_id;

    -- 2. Crear el usuario administrador
    new_user_id := auth.admin_create_user(
        p_admin_email,
        p_admin_password,
        '{"raw_user_meta_data": {"is_superadmin": false}}'::jsonb
    );

    -- 3. Vincular el usuario al tenant
    INSERT INTO tenant_users (tenant_id, user_id, role)
    VALUES (new_tenant_id, new_user_id, 'admin');

    -- 4. Crear la sucursal principal
    INSERT INTO branches (tenant_id, name, is_main_branch, address_line_1, city, state, postal_code, country_id, timezone)
    VALUES (new_tenant_id, 'Sucursal Principal', true, p_physical_address_line1, p_physical_city, p_physical_state, p_physical_postal_code, p_country_id, p_default_timezone)
    RETURNING id INTO new_branch_id;

    -- 5. Devolver un resultado exitoso
    RETURN json_build_object(
        'success', true,
        'tenant_id', new_tenant_id,
        'user_id', new_user_id,
        'branch_id', new_branch_id
    );
EXCEPTION
    WHEN OTHERS THEN
        -- En caso de cualquier error, devolver un JSON con el mensaje de error
        RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."create_tenant_and_admin_logic"("p_business_name" "text", "p_country_id" "uuid", "p_default_language_code" "text", "p_default_currency_id" "uuid", "p_default_timezone" "text", "p_contact_phone" "text", "p_whatsapp_phone" "text", "p_commercial_email" "text", "p_legal_name" "text", "p_tax_id" "text", "p_billing_address" "text", "p_einvoicing_email" "text", "p_physical_address_line1" "text", "p_physical_address_line2" "text", "p_physical_city" "text", "p_physical_state" "text", "p_physical_postal_code" "text", "p_website" "text", "p_latitude" numeric, "p_longitude" numeric, "p_admin_email" "text", "p_admin_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tenant_user"("p_email" "text", "p_role_id" "uuid", "p_tenant_id" "uuid", "p_branch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_caller_role TEXT := (auth.jwt() -> 'app_metadata' ->> 'role');
    v_caller_tenant_id UUID := (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid;
    v_new_user_id UUID;
BEGIN
    -- Step 2a: Authorization Check
    IF v_caller_role NOT IN ('super_admin', 'tenant_super_admin', 'tenant_admin') THEN
        RAISE EXCEPTION 'Permission denied: You do not have rights to create users.';
    END IF;

    IF v_caller_role != 'super_admin' AND v_caller_tenant_id != p_tenant_id THEN
        RAISE EXCEPTION 'Permission denied: You can only create users within your own tenant.';
    END IF;

    -- Step 2b: Create the user in Supabase Auth via invitation
    SELECT auth.admin_create_user(p_email) INTO v_new_user_id;

    -- Step 2c: Assign role and tenancy using our helper function
    PERFORM public.set_user_assignment(
        p_target_user_id := v_new_user_id,
        p_tenant_id := p_tenant_id,
        p_role_id := p_role_id,
        p_branch_id := p_branch_id
    );

    -- Step 2d: Return a success message
    RETURN jsonb_build_object(
        'success', TRUE,
        'message', 'User invited successfully.',
        'user_id', v_new_user_id
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."create_tenant_user"("p_email" "text", "p_role_id" "uuid", "p_tenant_id" "uuid", "p_branch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tenant_with_admin"("name" "text", "subscription_status" "text", "country_id" "uuid", "default_language_code" "text", "default_currency_id" "uuid", "default_timezone" "text", "contact_phone" "text", "whatsapp_phone" "text", "commercial_email" "text", "legal_name" "text", "tax_id" "text", "billing_address" "text", "einvoicing_email" "text", "physical_address_line1" "text", "physical_address_line2" "text", "physical_city" "text", "physical_state" "text", "physical_postal_code" "text", "website" "text", "latitude" numeric, "longitude" numeric, "admin_email" "text", "admin_password" "text") RETURNS TABLE("created_tenant_id" "uuid")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    new_tenant_id UUID;
    tenant_admin_role_id UUID;
    new_user_id UUID;
BEGIN
    -- Paso 1: Crear el nuevo tenant (sin cambios)
    INSERT INTO tenants (
        name, subscription_status, country_id, default_language_code, default_currency_id, default_timezone,
        contact_phone, whatsapp_phone, commercial_email, legal_name, tax_id, billing_address, einvoicing_email,
        physical_address_line1, physical_address_line2, physical_city, physical_state, physical_postal_code,
        website, latitude, longitude
    ) VALUES (
        create_tenant_with_admin.name, create_tenant_with_admin.subscription_status, create_tenant_with_admin.country_id,
        create_tenant_with_admin.default_language_code, create_tenant_with_admin.default_currency_id, create_tenant_with_admin.default_timezone,
        create_tenant_with_admin.contact_phone, create_tenant_with_admin.whatsapp_phone, create_tenant_with_admin.commercial_email,
        create_tenant_with_admin.legal_name, create_tenant_with_admin.tax_id, create_tenant_with_admin.billing_address,
        create_tenant_with_admin.einvoicing_email, create_tenant_with_admin.physical_address_line1,
        create_tenant_with_admin.physical_address_line2, create_tenant_with_admin.physical_city,
        create_tenant_with_admin.physical_state, create_tenant_with_admin.physical_postal_code,
        create_tenant_with_admin.website, create_tenant_with_admin.latitude, create_tenant_with_admin.longitude
    ) RETURNING id INTO new_tenant_id;

    -- Paso 2: Obtener el ID del rol 'tenant_super_admin' (sin cambios)
    SELECT id INTO tenant_admin_role_id FROM roles WHERE roles.name = 'tenant_super_admin' LIMIT 1;
    IF tenant_admin_role_id IS NULL THEN
        RAISE EXCEPTION 'El rol "tenant_super_admin" no fue encontrado.';
    END IF;

    -- Paso 3: Crear el nuevo usuario (REFACTORIZADO)
    -- Se inserta solo la información de identidad en la tabla 'users'.
    INSERT INTO users (email, password_hash)
    VALUES (
        create_tenant_with_admin.admin_email,
        crypt(create_tenant_with_admin.admin_password, gen_salt('bf'))
    ) RETURNING id INTO new_user_id;

    -- Paso 4: Crear la asignación en la nueva tabla (NUEVO)
    -- Se vincula el usuario, el tenant y el rol en 'user_assignments'.
    INSERT INTO user_assignments (user_id, tenant_id, role_id)
    VALUES (new_user_id, new_tenant_id, tenant_admin_role_id);

    -- Paso 5: Devolver el ID del tenant creado (sin cambios)
    RETURN QUERY SELECT new_tenant_id;

END;
$$;


