    CONSTRAINT "treatment_prototypes_type_check" CHECK (("type" = ANY (ARRAY['treatment'::"text", 'project'::"text"])))
);


ALTER TABLE "public"."treatments" OWNER TO "postgres";


COMMENT ON TABLE "public"."treatments" IS 'Plantillas maestras para tratamientos (Glamatica) o proyectos (Tattoo Suite).';



COMMENT ON COLUMN "public"."treatments"."upfront_price" IS 'Precio total del tratamiento si se paga de contado.';



COMMENT ON COLUMN "public"."treatments"."financed_price" IS 'Precio total del tratamiento si se paga de forma financiada.';



CREATE OR REPLACE FUNCTION "public"."create_treatment"("p_tenant_id" "uuid", "p_name" "text", "p_description" "text", "p_type" "text", "p_upfront_price" numeric, "p_financed_price" numeric, "p_sessions" "jsonb") RETURNS "public"."treatments"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    new_treatment public.treatments;
    session_data jsonb;
    new_session_id uuid;
    item_data jsonb;
BEGIN
    INSERT INTO public.treatments (tenant_id, name, description, type, upfront_price, financed_price)
    VALUES (p_tenant_id, p_name, p_description, p_type, p_upfront_price, p_financed_price)
    RETURNING * INTO new_treatment;

    IF p_sessions IS NOT NULL AND jsonb_array_length(p_sessions) > 0 THEN
        FOR session_data IN SELECT * FROM jsonb_array_elements(p_sessions) LOOP
            INSERT INTO public.treatment_sessions (
                treatment_id,
                session_number,
                name,
                description,
                payment_percentage,
                fixed_payment_amount
            )
            VALUES (
                new_treatment.id,
                (session_data->>'session_number')::int,
                session_data->>'name',
                session_data->>'description',
                (NULLIF(session_data->>'payment_percentage', 'null'))::numeric,
                (NULLIF(session_data->>'fixed_payment_amount', 'null'))::numeric
            )
            RETURNING id INTO new_session_id;

            IF session_data->'items' IS NOT NULL AND jsonb_array_length(session_data->'items') > 0 THEN
                FOR item_data IN SELECT * FROM jsonb_array_elements(session_data->'items') LOOP
                    INSERT INTO public.treatment_session_items (
                        session_id,
                        product_id,
                        service_id,
                        quantity,
                        notes
                    )
                    VALUES (
                        new_session_id,
                        (item_data->>'product_id')::uuid,
                        (item_data->>'service_id')::uuid,
                        (item_data->>'quantity')::int,
                        item_data->>'notes'
                    );
                END LOOP;
            END IF;
        END LOOP;
    END IF;

    RETURN new_treatment;
END;
$$;


