CREATE OR REPLACE FUNCTION "public"."disconnect_google_provider"("p_tenant_id" "uuid", "p_provider" "text", "p_requesting_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Primero, verificamos si el usuario autenticado es un superadministrador.
    -- Esta es una capa de seguridad crucial.
    IF NOT EXISTS (
        SELECT 1
        FROM auth.users u, jsonb_array_elements(u.raw_app_meta_data -> 'assignments') AS assignment
        WHERE u.id = p_requesting_user_id
          AND (assignment ->> 'role') = 'super_admin'
    ) THEN
        RETURN json_build_object('success', false, 'message', 'Acceso no autorizado. Se requiere ser superadministrador.');
    END IF;

    -- Procedemos a eliminar la integración específica para el tenant dado.
    DELETE FROM public.tenant_integrations
    WHERE tenant_id = p_tenant_id AND provider = p_provider;

    -- La variable 'FOUND' en PL/pgSQL es verdadera si la última operación (DELETE) afectó al menos una fila.
    IF FOUND THEN
        RETURN json_build_object('success', true, 'message', 'Integración desconectada correctamente.');
    ELSE
        -- Si no se encontró ninguna fila para eliminar, informamos que no existía.
        RETURN json_build_object('success', false, 'message', 'No se encontró una integración activa de este tipo para el tenant especificado.');
    END IF;

EXCEPTION
    -- Capturamos cualquier otro error que pueda ocurrir durante la ejecución.
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', 'Ocurrió un error interno al intentar desconectar la integración.');
END;
$$;


ALTER FUNCTION "public"."disconnect_google_provider"("p_tenant_id" "uuid", "p_provider" "text", "p_requesting_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_service"("p_attention_service_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id uuid;
    v_branch_id uuid;
    v_user_id uuid;
BEGIN
    -- Update the service status and end time
    UPDATE public.attention_services
    SET
        status = 'Finalizado',
        end_time = (now() AT TIME ZONE 'UTC')::time
    WHERE id = p_attention_service_id
    RETURNING tenant_id, branch_id, user_id INTO v_tenant_id, v_branch_id, v_user_id;

    -- Insert a record into the status history table
    IF FOUND THEN
        INSERT INTO public.attention_service_status_history
            (attention_service_id, status, tenant_id, branch_id, user_id)
        VALUES
            (p_attention_service_id, 'Finalizado', v_tenant_id, v_branch_id, v_user_id);
    END IF;
END;
$$;


ALTER FUNCTION "public"."end_service"("p_attention_service_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_test_email"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_super_admin_user_id UUID;
    v_new_job public.email_queue;
BEGIN
    -- 1. Encontrar al super_admin del sistema usando la tabla de asignaciones
    SELECT ua.user_id INTO v_super_admin_user_id
    FROM public.user_assignments ua
    JOIN public.roles r ON ua.role_id = r.id
    WHERE r.name = 'super_admin'
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'No se encontró al usuario super_admin del sistema.');
    END IF;

    -- 2. Insertar el trabajo en la cola y devolverlo
    INSERT INTO public.email_queue (recipient_user_id, template_type, template_data)
    VALUES (
        v_super_admin_user_id,
        'WELCOME_USER',
        jsonb_build_object('user_name', 'Super Admin (Prueba de Cola)')
    ) RETURNING * INTO v_new_job;

    RETURN jsonb_build_object('success', true, 'job', row_to_json(v_new_job));

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'message', 'Error inesperado al encolar: ' || SQLERRM);
END;
$$;


ALTER FUNCTION "public"."enqueue_test_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_attention_service"("p_attention_service_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id uuid;
    v_branch_id uuid;
    v_user_id uuid;
BEGIN
    -- Obtener IDs necesarios del servicio de atención
    SELECT tenant_id, branch_id, user_id INTO v_tenant_id, v_branch_id, v_user_id
    FROM public.attention_services
    WHERE id = p_attention_service_id;

    -- Actualizar el estado del servicio y la hora de finalización
    UPDATE public.attention_services
    SET 
        status = 'Finalizado',
        end_time = now()
    WHERE id = p_attention_service_id;

    -- Insertar un registro en el historial de estados
    INSERT INTO public.attention_service_status_history
        (attention_service_id, status, tenant_id, branch_id, user_id)
    VALUES
        (p_attention_service_id, 'Finalizado', v_tenant_id, v_branch_id, v_user_id);
END;
$$;


