CREATE OR REPLACE FUNCTION "public"."get_current_turns_for_branch"("p_branch_id" "uuid") RETURNS TABLE("id" "uuid", "branch_id" "uuid", "client_id" "uuid", "stylist_id" "uuid", "status" "public"."turn_status", "called_at" timestamp with time zone, "tenant_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "clients" "jsonb", "users" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RAISE NOTICE 'Fetching turns for branch: %', p_branch_id;

  RETURN QUERY
  SELECT
    t.id,
    t.branch_id,
    t.client_id,
    t.stylist_id,
    t.status,
    t.called_at,
    t.tenant_id,
    t.created_at,
    t.updated_at,
    jsonb_build_object('name', c.name) AS clients,
    jsonb_build_object('first_name', u.raw_user_meta_data->>'first_name', 'last_name', u.raw_user_meta_data->>'last_name') AS users
  FROM
    public.turns t
  LEFT JOIN
    public.clients c ON t.client_id = c.id
  LEFT JOIN
    auth.users u ON t.stylist_id = u.id
  WHERE
    t.branch_id = p_branch_id AND
    t.status IN ('waiting', 'called');
END;
$$;


