CREATE OR REPLACE FUNCTION "public"."get_investor_dashboard_data"("p_user_id" "uuid", "p_platform_id" "uuid") RETURNS TABLE("platform_name" "text", "investment_share" numeric, "mrr" numeric, "arr" numeric, "my_mrr_share" numeric, "my_arr_share" numeric, "total_revenue_last_30_days" numeric, "my_revenue_share_last_30" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_share NUMERIC;
    v_platform_name TEXT;
BEGIN
    -- Obtener la participación del inversor y el nombre de la plataforma.
    SELECT ips.investment_share, p.name
    INTO v_share, v_platform_name
    FROM public.investor_platform_shares ips
    JOIN public.platforms p ON ips.platform_id = p.id
    WHERE ips.user_id = p_user_id AND ips.platform_id = p_platform_id;

    -- Si no se encuentra participación, no devolver filas.
    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- Devolver las métricas de la plataforma multiplicadas por la participación del inversor.
    RETURN QUERY
    SELECT
        v_platform_name as platform_name,
        v_share as investment_share,
        stats.mrr,
        stats.arr,
        stats.mrr * v_share AS my_mrr_share,
        stats.arr * v_share AS my_arr_share,
        stats.total_revenue_last_30_days,
        stats.total_revenue_last_30_days * v_share AS my_revenue_share_last_30
    FROM public.get_platform_financial_stats(p_platform_id) stats;
END;
$$;


ALTER FUNCTION "public"."get_investor_dashboard_data"("p_user_id" "uuid", "p_platform_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_investor_dashboard_data"("p_user_id" "uuid", "p_platform_id" "uuid") IS 'Calcula las métricas del dashboard para un inversor, mostrando su participación sobre los ingresos de una plataforma específica.';



CREATE OR REPLACE FUNCTION "public"."get_investors"() RETURNS TABLE("user_id" "uuid", "email" "text", "full_name" "text", "avatar_url" "text", "platform_id" "uuid", "platform_name" "text", "stake_percentage" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        u.id as user_id,
        u.email,
        u.raw_user_meta_data->>'full_name' as full_name,
        u.raw_user_meta_data->>'avatar_url' as avatar_url,
        p.id as platform_id,
        p.name as platform_name,
        ips.investment_share * 100 as stake_percentage
    FROM
        public.investor_platform_shares ips
    JOIN
        auth.users u ON ips.user_id = u.id
    JOIN
        public.platforms p ON ips.platform_id = p.id
    ORDER BY
        u.email, p.name;
END;
$$;


