CREATE OR REPLACE FUNCTION "public"."get_next_document_number"("p_tenant_id" "uuid", "p_document_type" "text", "p_branch_id" "uuid" DEFAULT NULL::"uuid", "p_context_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    sequence_rec RECORD;
    branch_rec RECORD;
    formatted_number text;
    next_number integer;
    current_ts timestamptz := now(); -- Get current timestamp once
BEGIN
    -- Find the appropriate sequence and lock the row for update
    SELECT *
    INTO sequence_rec
    FROM public.document_sequences
    WHERE tenant_id = p_tenant_id
      AND document_type = p_document_type
      AND (branch_id = p_branch_id OR branch_id IS NULL)
      AND is_active = true
    ORDER BY branch_id DESC NULLS LAST
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No active document sequence found for document type %', p_document_type;
    END IF;

    -- Get the number for the current document
    next_number := sequence_rec.current_number;

    -- Increment the number for the next call
    UPDATE public.document_sequences
    SET current_number = current_number + 1
    WHERE id = sequence_rec.id;

    -- Start with the format template
    formatted_number := COALESCE(sequence_rec.format_template, '{prefix}{sequence}');

    -- Replace date placeholders
    formatted_number := replace(formatted_number, '{YYYY}', to_char(current_ts, 'YYYY'));
    formatted_number := replace(formatted_number, '{YY}', to_char(current_ts, 'YY'));
    formatted_number := replace(formatted_number, '{MM}', to_char(current_ts, 'MM'));
    formatted_number := replace(formatted_number, '{DD}', to_char(current_ts, 'DD'));

    -- Replace other placeholders
    formatted_number := replace(formatted_number, '{prefix}', COALESCE(sequence_rec.prefix, ''));
    formatted_number := replace(formatted_number, '{sequence}', LPAD(next_number::text, sequence_rec.padding, '0'));

    IF p_branch_id IS NOT NULL THEN
        SELECT code INTO branch_rec FROM public.branches WHERE id = p_branch_id;
        IF FOUND THEN
            formatted_number := replace(formatted_number, '{branch_code}', COALESCE(branch_rec.code, ''));
        END IF;
    END IF;

    IF p_context_data ? 'direction' THEN
        formatted_number := replace(formatted_number, '{direction}', p_context_data->>'direction');
    END IF;

    RETURN formatted_number;
END;
$$;


ALTER FUNCTION "public"."get_next_document_number"("p_tenant_id" "uuid", "p_document_type" "text", "p_branch_id" "uuid", "p_context_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_next_document_number"("p_tenant_id" "uuid", "p_document_type" "text", "p_branch_id" "uuid", "p_context_data" "jsonb") IS 'V3: Safely retrieves the next formatted document number, supporting date placeholders like {YYYY}, {MM}, {DD}.';



CREATE OR REPLACE FUNCTION "public"."get_or_create_tv_display"("p_id" "uuid" DEFAULT NULL::"uuid", "p_registration_code" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "branch_id" "uuid", "registration_code" "text", "is_registered" boolean, "registered_at" timestamp with time zone, "last_heartbeat" timestamp with time zone, "media_playlist_id" "uuid", "tenant_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  tv_record RECORD;
  generated_code TEXT;
BEGIN
  -- Priority 1: Use the provided ID if it exists
  IF p_id IS NOT NULL THEN
    SELECT * INTO tv_record FROM public.tv_displays WHERE public.tv_displays.id = p_id;
    IF FOUND THEN
      RETURN QUERY SELECT tv_record.id, tv_record.branch_id, tv_record.registration_code, tv_record.is_registered, tv_record.registered_at, tv_record.last_heartbeat, tv_record.media_playlist_id, tv_record.tenant_id, tv_record.created_at, tv_record.updated_at;
      RETURN;
    END IF;
    -- If ID is provided but not found, we will fall through to create a new record.
    -- This handles cases where localStorage has a stale ID.
  END IF;

  -- Priority 2: Use the registration code if provided
  IF p_registration_code IS NOT NULL THEN
    SELECT * INTO tv_record FROM public.tv_displays WHERE public.tv_displays.registration_code = p_registration_code;
    IF FOUND THEN
      RETURN QUERY SELECT tv_record.id, tv_record.branch_id, tv_record.registration_code, tv_record.is_registered, tv_record.registered_at, tv_record.last_heartbeat, tv_record.media_playlist_id, tv_record.tenant_id, tv_record.created_at, tv_record.updated_at;
      RETURN;
    END IF;
    -- If code is provided but not found, return nothing. Client should redirect.
    RETURN;
  END IF;

  -- Priority 3: Create a new record if no valid identifier was provided
  LOOP
    generated_code := upper(substr(md5(random()::text), 0, 7));
    IF NOT EXISTS (SELECT 1 FROM public.tv_displays WHERE public.tv_displays.registration_code = generated_code) THEN
      EXIT;
    END IF;
  END LOOP;

  INSERT INTO public.tv_displays (registration_code, is_registered)
  VALUES (generated_code, false)
  RETURNING * INTO tv_record;

  RETURN QUERY SELECT tv_record.id, tv_record.branch_id, tv_record.registration_code, tv_record.is_registered, tv_record.registered_at, tv_record.last_heartbeat, tv_record.media_playlist_id, tv_record.tenant_id, tv_record.created_at, tv_record.updated_at;
END;
$$;


ALTER FUNCTION "public"."get_or_create_tv_display"("p_id" "uuid", "p_registration_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payslip_details"("p_payslip_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_tenant_id uuid;
  v_payslip_user_id uuid;
  v_tenant_info jsonb;
  v_payslip_info jsonb;
  v_commissions jsonb;
  v_signature_info jsonb;
  v_result jsonb;
BEGIN
  -- Get tenant_id and user_id from the payslip
  SELECT tenant_id, user_id INTO v_tenant_id, v_payslip_user_id FROM public.payslips WHERE id = p_payslip_id;

  -- Get tenant info
  SELECT jsonb_build_object(
    'logo_url', logo_url,
    'name', name,
    'billing_address', billing_address,
    'tax_id', tax_id,
    'contact_phone', contact_phone
  ) INTO v_tenant_info FROM public.tenants WHERE id = v_tenant_id;

  -- Get payslip info
  SELECT to_jsonb(p.*) INTO v_payslip_info FROM public.payslips p WHERE id = p_payslip_id;

  -- Get signature info
  SELECT jsonb_build_object('google_drive_file_id', cpe.google_drive_file_id)
  INTO v_signature_info
  FROM public.commission_payment_evidences cpe
  WHERE cpe.payslip_id = p_payslip_id
  ORDER BY cpe.created_at DESC
  LIMIT 1;

  -- Get commission details
  WITH commissions_base AS (
    SELECT 
      ec.id,
      ec.created_at,
      ec.commission_amount,
      ec.sales_item_id,
      s.client_id
    FROM public.payslip_commissions pc
    JOIN public.earned_commissions ec ON pc.commission_id = ec.id
    JOIN public.sales_items si ON ec.sales_item_id = si.id
    JOIN public.sales s ON si.sale_id = s.id
    WHERE pc.payslip_id = p_payslip_id
  )
  SELECT jsonb_agg(jsonb_build_object(
    'attention_date', cb.created_at,
    'item_name', si.description,
    'item_price', si.unit_price,
    'commission_amount', cb.commission_amount,
    'client_name', c.name
  ))
  INTO v_commissions
  FROM commissions_base cb
  JOIN public.sales_items si ON cb.sales_item_id = si.id
  LEFT JOIN public.clients c ON cb.client_id = c.id;

  -- Combine all information
  v_result := jsonb_build_object(
    'tenant', v_tenant_info,
    'payslip', v_payslip_info,
    'signature', v_signature_info,
    'commissions', v_commissions
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_payslip_details"("p_payslip_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_commissions"("p_tenant_id" "uuid", "p_branch_id" "uuid" DEFAULT NULL::"uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("total_pending_commissions" numeric)
