CREATE OR REPLACE FUNCTION "public"."reject_product_transfer"("p_transfer_id" "uuid", "p_tenant_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    updated_transfer record;
    v_origin_branch_id uuid;
    v_user_is_in_origin_branch boolean;
BEGIN
    -- 1. Check if the transfer exists and get its origin branch
    SELECT origin_branch_id INTO v_origin_branch_id
    FROM public.product_transfers
    WHERE id = p_transfer_id AND tenant_id = p_tenant_id AND status = 'solicitado';

    IF v_origin_branch_id IS NULL THEN
        RAISE EXCEPTION 'Transfer not found, not in "solicitado" state, or you do not have permission.';
    END IF;

    -- 2. Check if the user is assigned to the origin branch
    SELECT EXISTS (
        SELECT 1
        FROM auth.users u,
             jsonb_array_elements(u.raw_app_meta_data->'assignments') as assignment
        WHERE u.id = p_user_id
          AND assignment->>'branch_id' = v_origin_branch_id::text
          AND assignment->>'tenant_id' = p_tenant_id::text
    ) INTO v_user_is_in_origin_branch;

    IF NOT v_user_is_in_origin_branch THEN
        RAISE EXCEPTION 'You do not have permission to reject this transfer.';
    END IF;

    -- 3. Update the transfer status to 'rechazado'
    UPDATE public.product_transfers
    SET status = 'rechazado', updated_at = now()
    WHERE id = p_transfer_id
    RETURNING * INTO updated_transfer;

    RETURN to_jsonb(updated_transfer);
END;
$$;


ALTER FUNCTION "public"."reject_product_transfer"("p_transfer_id" "uuid", "p_tenant_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."renew_subscription"("p_tenant_id" "uuid", "p_plan_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    previous_subscription RECORD;
    new_start_date TIMESTAMPTZ;
    new_end_date TIMESTAMPTZ;
    plan_duration_months INT;
    new_subscription_id UUID;
    generated_invoice_id UUID;
BEGIN
    -- 1. Encontrar la suscripción más reciente (activa o no) para este tenant.
    SELECT * INTO previous_subscription
    FROM public.tenant_subscriptions
    WHERE tenant_id = p_tenant_id
    ORDER BY end_date DESC NULLS LAST, created_at DESC
    LIMIT 1;

    -- 2. Determinar la fecha de inicio de la nueva suscripción.
    IF previous_subscription IS NOT NULL AND previous_subscription.end_date IS NOT NULL THEN
        -- Renovación: la nueva suscripción empieza donde terminó la anterior.
        new_start_date := previous_subscription.end_date;
    ELSE
        -- Primera suscripción después de un trial o si no hay registro previo.
        new_start_date := now();
    END IF;

    -- 3. Calcular la nueva fecha de finalización.
    SELECT billing_frequency_months INTO plan_duration_months
    FROM public.subscription_plans
    WHERE id = p_plan_id;

    IF plan_duration_months IS NULL THEN
        RAISE EXCEPTION 'No se pudo encontrar la duración para el plan ID %.', p_plan_id;
    END IF;

    new_end_date := new_start_date + (plan_duration_months || ' months')::interval;

    -- 4. Crear la nueva suscripción de pago.
    INSERT INTO public.tenant_subscriptions (
        tenant_id,
        subscription_plan_id,
        is_trial,
        start_date,
        end_date,
        is_active
    ) VALUES (
        p_tenant_id,
        p_plan_id,
        FALSE,
        new_start_date,
        new_end_date,
        TRUE
    ) RETURNING id INTO new_subscription_id;

    -- 5. Actualizar el estado del tenant a 'active'.
    UPDATE public.tenants
    SET subscription_status = 'active'
    WHERE id = p_tenant_id;

    -- 6. Generar la factura para la nueva suscripción.
    SELECT public.generate_invoice_for_subscription(new_subscription_id)
    INTO generated_invoice_id;

    RAISE NOTICE 'Suscripción renovada con ID: %. Factura generada con ID: %', new_subscription_id, generated_invoice_id;

    -- 7. Devolver el ID de la nueva suscripción.
    RETURN new_subscription_id;
END;
$$;


ALTER FUNCTION "public"."renew_subscription"("p_tenant_id" "uuid", "p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reschedule_attention"("p_attention_id" "uuid", "p_new_datetime" timestamp with time zone, "p_reason" "text", "p_fault" "text", "p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_original_date TIMESTAMPTZ;
    v_client_id UUID;
BEGIN
    -- Get original date and client_id from the attention
    SELECT attention_datetime, client_id
    INTO v_original_date, v_client_id
    FROM attentions
    WHERE id = p_attention_id;

    -- Update the attention with the new date and time
    UPDATE attentions
    SET attention_datetime = p_new_datetime
    WHERE id = p_attention_id;

    -- Insert a record into the rescheduled_attentions table
    INSERT INTO rescheduled_attentions (attention_id, client_id, original_date, new_date, reason, user_id, fault)
    VALUES (p_attention_id, v_client_id, v_original_date, p_new_datetime, p_reason, p_user_id, p_fault);

END;
$$;


ALTER FUNCTION "public"."reschedule_attention"("p_attention_id" "uuid", "p_new_datetime" timestamp with time zone, "p_reason" "text", "p_fault" "text", "p_user_id" "uuid") OWNER TO "postgres";


