CREATE OR REPLACE FUNCTION "public"."search_clients"("p_tenant_id" "uuid", "p_branch_id" "text", "p_search_term" "text", "p_show_inactive" boolean) RETURNS TABLE("id" "uuid", "name" "text", "email" "text", "phone" "text", "document_type_id" "uuid", "document_number" "text", "is_active" boolean, "parent_client_id" "uuid", "tenant_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "parent_client_name" "text", "branches" "jsonb")
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    search_words TEXT[];
    filtered_words TEXT[];
    search_query TEXT;
    final_query TEXT;
    branch_uuid UUID;
    word TEXT;
BEGIN
    -- Handle 'all' branches case
    IF p_branch_id = 'all' THEN
        branch_uuid := NULL;
    ELSE
        branch_uuid := p_branch_id::UUID;
    END IF;

    -- Build the full-text search query
    IF p_search_term IS NOT NULL AND p_search_term <> '' THEN
        search_words := string_to_array(lower(p_search_term), ' ');
        
        -- Filter out empty strings
        FOREACH word IN ARRAY search_words
        LOOP
            IF word <> '' THEN
                filtered_words := array_append(filtered_words, word || ':*');
            END IF;
        END LOOP;

        IF array_length(filtered_words, 1) > 0 THEN
            search_query := array_to_string(filtered_words, ' & ');
        ELSE
            search_query := NULL;
        END IF;
    ELSE
        search_query := NULL;
    END IF;

    -- Construct the final query
    final_query := '
        WITH client_branches_agg AS (
            SELECT 
                cb.client_id, 
                jsonb_agg(jsonb_build_object(''id'', b.id, ''name'', b.name)) as branches
            FROM client_branches cb
            JOIN branches b ON cb.branch_id = b.id
            WHERE cb.tenant_id = $1
            GROUP BY cb.client_id
        )
        SELECT
            c.id,
            c.name,
            c.email,
            c.phone,
            c.document_type_id,
            c.document_number,
            c.is_active,
            c.parent_client_id,
            c.tenant_id,
            c.created_at,
            c.updated_at,
            pc.name as parent_client_name,
            cba.branches
        FROM
            clients c
        LEFT JOIN
            clients pc ON c.parent_client_id = pc.id
        LEFT JOIN 
            client_branches_agg cba ON c.id = cba.client_id
        WHERE
            c.tenant_id = $1';

    IF branch_uuid IS NOT NULL THEN
        final_query := final_query || '
            AND c.id IN (SELECT client_id FROM client_branches WHERE branch_id = $2 AND tenant_id = $1)';
    END IF;

    IF NOT p_show_inactive THEN
        final_query := final_query || '
            AND c.is_active = TRUE';
    END IF;

    IF search_query IS NOT NULL THEN
        final_query := final_query || format(' AND c.fts @@ to_tsquery(''simple'', %L)', search_query);
    END IF;

    final_query := final_query || '
        ORDER BY c.name;';

    -- Execute the query
    IF branch_uuid IS NOT NULL THEN
         RETURN QUERY EXECUTE final_query USING p_tenant_id, branch_uuid;
    ELSE
         RETURN QUERY EXECUTE final_query USING p_tenant_id;
    END IF;

END;
$_$;


ALTER FUNCTION "public"."search_clients"("p_tenant_id" "uuid", "p_branch_id" "text", "p_search_term" "text", "p_show_inactive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_products"("p_tenant_id" "uuid", "p_search_term" "text" DEFAULT NULL::"text", "p_show_inactive" boolean DEFAULT false, "p_category_name" "text" DEFAULT NULL::"text", "p_brand_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "is_active" boolean, "category" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "cost_price" numeric, "last_purchase_cost" numeric, "average_cost" numeric, "brand_id" "uuid", "barcode" "text", "sku" "text", "tenant_id" "uuid", "name_i18n" "jsonb", "description_i18n" "jsonb", "unit_of_measure_id" "uuid", "package_content_quantity" numeric, "allow_decimal_sale" boolean)
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    search_words TEXT[];
    word TEXT;
    query_conditions TEXT[] := ARRAY[]::TEXT[];
    final_query TEXT;
BEGIN
    -- Split the search term into words
    IF p_search_term IS NOT NULL AND p_search_term <> '' THEN
        search_words := string_to_array(lower(p_search_term), ' ');
    ELSE
        search_words := ARRAY[]::TEXT[];
    END IF;

    -- Build the query conditions for each word
    FOREACH word IN ARRAY search_words
    LOOP
        IF word <> '' THEN
            query_conditions := array_append(
                query_conditions,
                format(
                    '(p.name ILIKE %1$L OR p.description ILIKE %1$L OR p.sku ILIKE %1$L OR p.barcode ILIKE %1$L)',
                    '%' || word || '%'
                )
            );
        END IF;
    END LOOP;

    -- Construct the final query
    final_query := '
        SELECT
            p.id,
            p.name,
            p.description,
            p.is_active,
            p.category,
            p.created_at,
            p.updated_at,
            p.cost_price,
            p.last_purchase_cost,
            p.average_cost,
            p.brand_id,
            p.barcode,
            p.sku,
            p.tenant_id,
            p.name_i18n,
            p.description_i18n,
            p.unit_of_measure_id,      -- Campo añadido
            p.package_content_quantity, -- Campo añadido
            p.allow_decimal_sale       -- Campo añadido
        FROM
            products p
        WHERE
            p.tenant_id = $1';

    IF NOT p_show_inactive THEN
        final_query := final_query || '
            AND p.is_active = TRUE';
    END IF;

    IF p_category_name IS NOT NULL AND p_category_name <> '' THEN
        final_query := final_query || format('
            AND p.category = %L', p_category_name);
    END IF;

    IF p_brand_id IS NOT NULL THEN
        final_query := final_query || format('
            AND p.brand_id = %L', p_brand_id);
    END IF;

    IF array_length(query_conditions, 1) > 0 THEN
        final_query := final_query || '
            AND (' || array_to_string(query_conditions, ' AND ') || ')';
    END IF;

    final_query := final_query || '
        ORDER BY p.name;';

    -- Execute the query
    RETURN QUERY EXECUTE final_query USING p_tenant_id;
END;
$_$;


ALTER FUNCTION "public"."search_products"("p_tenant_id" "uuid", "p_search_term" "text", "p_show_inactive" boolean, "p_category_name" "text", "p_brand_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_products"("p_tenant_id" "uuid", "p_search_term" "text", "p_show_inactive" boolean, "p_category_id" "uuid", "p_brand_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "cost_price" numeric, "last_purchase_cost" numeric, "average_cost" numeric, "brand_id" "uuid", "barcode" "text", "sku" "text", "tenant_id" "uuid", "name_i18n" "jsonb", "description_i18n" "jsonb", "unit_of_measure_id" "uuid", "package_content_quantity" numeric, "allow_decimal_sale" boolean, "product_images" "jsonb", "product_categories" "jsonb")
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    search_words TEXT[];
    word TEXT;
    query_conditions TEXT[] := ARRAY[]::TEXT[];
    final_query TEXT;
BEGIN
    -- Split the search term into words
    IF p_search_term IS NOT NULL AND p_search_term <> '' THEN
        search_words := string_to_array(lower(p_search_term), ' ');
    ELSE
        search_words := ARRAY[]::TEXT[];
    END IF;

    -- Build the query conditions for each word
    FOREACH word IN ARRAY search_words
    LOOP
        IF word <> '' THEN
            query_conditions := array_append(
                query_conditions,
                format(
                    '(p.name ILIKE %1$L OR p.description ILIKE %1$L OR p.sku ILIKE %1$L OR p.barcode ILIKE %1$L)',
                    '%' || word || '%'
                )
            );
        END IF;
    END LOOP;

    -- Construct the final query
    final_query := '
        SELECT
            p.id,
            p.name,
            p.description,
            p.is_active,
            p.created_at,
            p.updated_at,
            p.cost_price,
            p.last_purchase_cost,
            p.average_cost,
            p.brand_id,
            p.barcode,
            p.sku,
            p.tenant_id,
            p.name_i18n,
            p.description_i18n,
            p.unit_of_measure_id,
            p.package_content_quantity,
            p.allow_decimal_sale,
            COALESCE(pi.images, ''[]''::jsonb) AS product_images,
            COALESCE(pc.categories, ''[]''::jsonb) as product_categories
        FROM
            public.products p
        LEFT JOIN (
            SELECT
                product_id,
                jsonb_agg(jsonb_build_object(
                    ''id'', id,
                    ''image_url'', image_url,
                    ''sort_order'', sort_order,
                    ''is_primary'', is_primary
                ) ORDER BY is_primary DESC, sort_order ASC) AS images
            FROM
                public.product_images
            GROUP BY
                product_id
        ) pi ON p.id = pi.product_id
        LEFT JOIN (
            SELECT
                pca.product_id,
                jsonb_agg(jsonb_build_object(''id'', pc.id, ''name'', pc.name) ORDER BY pc.name) AS categories
            FROM
                public.product_category_assignments pca
            JOIN
                public.product_categories pc ON pca.category_id = pc.id
            GROUP BY
                pca.product_id
        ) pc ON p.id = pc.product_id
        WHERE
            p.tenant_id = $1';

    IF NOT p_show_inactive THEN
        final_query := final_query || '
            AND p.is_active = TRUE';
    END IF;

    -- Use the new p_category_id to filter
    IF p_category_id IS NOT NULL THEN
        final_query := final_query || format('
            AND p.id IN (SELECT product_id FROM public.product_category_assignments WHERE category_id = %L)', p_category_id);
    END IF;

    IF p_brand_id IS NOT NULL THEN
        final_query := final_query || format('
            AND p.brand_id = %L', p_brand_id);
    END IF;

    IF array_length(query_conditions, 1) > 0 THEN
        final_query := final_query || '
            AND (' || array_to_string(query_conditions, ' AND ') || ')';
    END IF;

    final_query := final_query || '
        ORDER BY p.name;';

    -- Execute the query
    RETURN QUERY EXECUTE final_query USING p_tenant_id;
END;
$_$;


ALTER FUNCTION "public"."search_products"("p_tenant_id" "uuid", "p_search_term" "text", "p_show_inactive" boolean, "p_category_id" "uuid", "p_brand_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_services"("p_tenant_id" "uuid", "p_search_term" "text", "p_category_id" "uuid", "p_show_inactive" boolean) RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "duration_minutes" integer, "is_active" boolean, "category_id" "uuid", "tenant_id" "uuid", "name_i18n" "jsonb", "description_i18n" "jsonb", "is_visible_on_microsite" boolean, "category_name" "text", "service_images" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
      s.id,
      s.name,
      s.description,
      s.duration_minutes,
      s.is_active,
      s.category_id,
      s.tenant_id,
      s.name_i18n,
      s.description_i18n,
      s.is_visible_on_microsite,
      sc.name as category_name,
      COALESCE(si_agg.images, '[]'::jsonb) AS service_images
  FROM public.services s
  LEFT JOIN public.service_categories sc ON s.category_id = sc.id
  LEFT JOIN (
      SELECT
          si_img.service_id,
          jsonb_agg(jsonb_build_object(
              'id', si_img.id,
              'image_url', si_img.image_url,
              'google_drive_file_id', si_img.google_drive_file_id,
              'sort_order', si_img.sort_order,
              'is_primary', si_img.is_primary
          ) ORDER BY si_img.is_primary DESC, si_img.sort_order ASC) AS images
      FROM
          public.service_images si_img
      GROUP BY
          si_img.service_id
  ) si_agg ON s.id = si_agg.service_id
  WHERE
      s.tenant_id = p_tenant_id
      AND (p_show_inactive OR s.is_active = TRUE)
      AND (p_category_id IS NULL OR s.category_id = p_category_id)
      AND (
          p_search_term IS NULL OR p_search_term = '' OR
          s.name ILIKE '%' || p_search_term || '%' OR
          s.description ILIKE '%' || p_search_term || '%'
      )
  ORDER BY s.name;
END;
$$;


ALTER FUNCTION "public"."search_services"("p_tenant_id" "uuid", "p_search_term" "text", "p_category_id" "uuid", "p_show_inactive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_electronic_document"("p_tenant_id" "uuid", "p_document_id" "uuid", "p_provider_slug" "text", "p_document_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_provider_config RECORD;
    v_tenant_integration RECORD;
    v_invoice_data JSONB;
    v_request_body JSONB;
    v_request_headers JSONB;
    v_request_url TEXT;
    v_response_content JSONB;
    v_http_method TEXT;
    v_auth_token TEXT;
    v_dataico_account_id TEXT;
    v_decrypted_credentials JSONB;
    v_service_role_key TEXT;
    v_supabase_url TEXT;
    v_edge_function_url TEXT;
    v_edge_function_response JSONB;
BEGIN
    -- 1. Fetch provider configuration from integration_providers
    SELECT
        ip.endpoints,
        ip.config_schema,
        ip.api_schema,
        ihm.method AS http_method,
        ibf.format AS body_format,
        iam.method AS auth_method,
        ip.http_headers,
        ip.authentication_config
    INTO v_provider_config
    FROM public.integration_providers ip
    JOIN public.integration_http_methods ihm ON ip.http_method_id = ihm.id
    JOIN public.integration_body_formats ibf ON ip.body_format_id = ibf.id
    JOIN public.integration_auth_methods iam ON ip.auth_method_id = iam.id
    WHERE ip.slug = p_provider_slug;

    IF v_provider_config.endpoints IS NULL THEN
        RAISE EXCEPTION 'Provider configuration not found for slug: %', p_provider_slug;
    END IF;

    -- 2. Fetch tenant-specific integration credentials
    SELECT encrypted_credentials, nonce, environment
    INTO v_tenant_integration
    FROM public.tenant_integrations
    WHERE tenant_id = p_tenant_id AND provider = p_provider_slug AND is_active = TRUE;

    IF v_tenant_integration.encrypted_credentials IS NULL THEN
        RAISE EXCEPTION 'Active tenant integration credentials not found for tenant % and provider %', p_tenant_id, p_provider_slug;
    END IF;

    -- 3. Fetch Glamtica invoice data
    SELECT to_jsonb(i.*) || jsonb_build_object('items', (SELECT jsonb_agg(ii.*) FROM public.invoice_items ii WHERE ii.invoice_id = i.id))
    INTO v_invoice_data
    FROM public.invoices i
    WHERE i.id = p_document_id AND i.tenant_id = p_tenant_id;

    IF v_invoice_data IS NULL THEN
        RAISE EXCEPTION 'Invoice data not found for document ID: %', p_document_id;
    END IF;

    -- 4. Prepare request URL
    v_request_url := v_provider_config.endpoints->>v_tenant_integration.environment;
    IF v_request_url IS NULL THEN
        RAISE EXCEPTION 'Endpoint URL not found for environment %', v_tenant_integration.environment;
    END IF;

    -- 5. Call an Edge Function to handle data mapping, decryption, and external API call
    -- This Edge Function will receive:
    -- - Glamtica invoice data (v_invoice_data)
    -- - Provider's api_schema (v_provider_config.api_schema)
    -- - Provider's http_headers (v_provider_config.http_headers)
    -- - Tenant's encrypted credentials (v_tenant_integration.encrypted_credentials, v_tenant_integration.nonce)
    -- - Dataico_account_id and Auth-token from config_schema (extracted from decrypted credentials)
    -- - Target API URL (v_request_url)
    -- - HTTP Method (v_provider_config.http_method)

    -- Get Supabase URL and Service Role Key for Edge Function invocation
    SELECT value INTO v_supabase_url FROM private.secrets WHERE key = 'supabase_url';
    SELECT value INTO v_service_role_key FROM private.secrets WHERE key = 'service_role_key';

    v_edge_function_url := v_supabase_url || '/functions/v1/map-and-send-dataico'; -- Name of the new Edge Function

    SELECT content INTO v_edge_function_response FROM net.http_post(
        url:= v_edge_function_url,
        body:= jsonb_build_object(
            'tenant_id', p_tenant_id,
            'document_id', p_document_id,
            'glamtica_invoice_data', v_invoice_data,
            'provider_api_schema', v_provider_config.api_schema,
            'provider_http_headers', v_provider_config.http_headers,
            'provider_endpoints', v_provider_config.endpoints,
            'tenant_encrypted_credentials', v_tenant_integration.encrypted_credentials,
            'tenant_nonce', v_tenant_integration.nonce,
            'tenant_environment', v_tenant_integration.environment,
            'http_method', v_provider_config.http_method,
            'body_format', v_provider_config.body_format
        ),
        headers:= jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_service_role_key -- Authorize Edge Function call
        )
    );

    -- 6. Handle response from Edge Function and update invoice status
    IF (v_edge_function_response->>'success')::BOOLEAN THEN
        -- Update invoice status, provider reference, etc.
        UPDATE public.invoices
        SET
            status = 'sent_to_dataico', -- Or a more specific status
            provider_reference_id = v_edge_function_response->>'dataico_document_id',
            -- Add other fields as needed from the response
            updated_at = NOW()
        WHERE id = p_document_id;

        RETURN jsonb_build_object('success', TRUE, 'message', 'Document sent successfully to Dataico.', 'dataico_response', v_edge_function_response);
    ELSE
        -- Log error and update invoice status
        UPDATE public.invoices
        SET
            status = 'failed_dataico_send',
            error_message = v_edge_function_response->>'error',
            updated_at = NOW()
        WHERE id = p_document_id;

        RAISE EXCEPTION 'Failed to send document to Dataico: %', v_edge_function_response->>'error';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        -- Log any unexpected errors
        RAISE EXCEPTION 'Error in send_electronic_document: %', SQLERRM;
END;
$$;


ALTER FUNCTION "public"."send_electronic_document"("p_tenant_id" "uuid", "p_document_id" "uuid", "p_provider_slug" "text", "p_document_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_active_integration"("p_integration_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_provider TEXT;
BEGIN
    -- 1. Verificar que el usuario solicitante es un super_admin usando la función de ayuda.
    IF NOT public.is_super_admin() THEN
        RAISE EXCEPTION 'Acceso denegado. Solo los super administradores pueden cambiar integraciones activas.';
    END IF;

    -- 2. Obtener el tenant_id y el provider de la integración que se va a activar.
    SELECT tenant_id, provider INTO v_tenant_id, v_provider
    FROM public.tenant_integrations
    WHERE id = p_integration_id;

    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'Integración no encontrada.';
    END IF;

    -- 3. Desactivar todas las demás integraciones para ese tenant y proveedor.
    UPDATE public.tenant_integrations
    SET is_active = false
    WHERE tenant_id = v_tenant_id
      AND provider = v_provider
      AND id != p_integration_id;

    -- 4. Activar la integración seleccionada.
    UPDATE public.tenant_integrations
    SET is_active = true
    WHERE id = p_integration_id;

END;
$$;


ALTER FUNCTION "public"."set_active_integration"("p_integration_id" "uuid") OWNER TO "postgres";


