CREATE OR REPLACE FUNCTION "public"."update_product_costs"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  costing_method text;
  current_avg_cost numeric;
  current_stock integer;
  new_avg_cost numeric;
BEGIN
  -- Obtener método de costeo de configuración
  SELECT value INTO costing_method 
  FROM settings 
  WHERE key = 'costing_method';
  
  -- Si no hay configuración, usar promedio por defecto
  IF costing_method IS NULL THEN
    costing_method := 'average';
  END IF;
  
  -- Obtener stock y costo promedio actual
  SELECT COALESCE(stock_quantity, 0), COALESCE(average_cost, 0)
  INTO current_stock, current_avg_cost
  FROM products 
  WHERE id = NEW.product_id;
  
  -- Actualizar stock y último costo de compra
  UPDATE products 
  SET stock_quantity = COALESCE(stock_quantity, 0) + NEW.quantity,
      last_purchase_cost = NEW.unit_cost
  WHERE id = NEW.product_id;
  
  -- Calcular y actualizar costo promedio
  IF costing_method = 'average' THEN
    IF current_stock = 0 OR current_avg_cost = 0 THEN
      new_avg_cost := NEW.unit_cost;
    ELSE
      new_avg_cost := ((current_avg_cost * current_stock) + (NEW.unit_cost * NEW.quantity)) / (current_stock + NEW.quantity);
    END IF;
    
    UPDATE products 
    SET average_cost = new_avg_cost,
        cost_price = new_avg_cost
    WHERE id = NEW.product_id;
  ELSIF costing_method = 'last_purchase' THEN
    UPDATE products 
    SET cost_price = NEW.unit_cost,
        average_cost = NEW.unit_cost
    WHERE id = NEW.product_id;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_product_costs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_product_images_order"("p_tenant_id" "uuid", "p_images_data" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Use a temporary table to hold the new order data
    CREATE TEMP TABLE new_order (
        id uuid,
        sort_order int
    ) ON COMMIT DROP;

    -- Insert the data from the JSONB array into the temp table
    INSERT INTO new_order (id, sort_order)
    SELECT
        (value->>'id')::uuid,
        (value->>'sort_order')::int
    FROM jsonb_array_elements(p_images_data);

    -- Update the product_images table by joining with the temp table
    UPDATE public.product_images AS pi
    SET sort_order = no.sort_order
    FROM new_order AS no
    WHERE pi.id = no.id AND pi.tenant_id = p_tenant_id;

END;
$$;


