CREATE OR REPLACE FUNCTION "public"."update_user_name"("user_id_to_update" "uuid", "new_first_name" "text", "new_last_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE auth.users
  SET
    raw_user_meta_data = raw_user_meta_data || jsonb_build_object(
      'first_name', new_first_name,
      'last_name', new_last_name
    )
  WHERE id = user_id_to_update;
END;
$$;


ALTER FUNCTION "public"."update_user_name"("user_id_to_update" "uuid", "new_first_name" "text", "new_last_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_user_password"("p_old_password" "text", "p_new_password" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    user_record RECORD;
    current_user_id UUID;
BEGIN
    -- 1. Get the current user's ID from the session context
    current_user_id := (current_setting('app.current_user_id', TRUE)::uuid);

    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'No active user session found.';
    END IF;

    -- 2. Find the user in auth.users table
    SELECT * INTO user_record
    FROM auth.users
    WHERE id = current_user_id;

    -- 3. Verify the old password
    IF user_record.encrypted_password IS NULL OR crypt(p_old_password, user_record.encrypted_password) <> user_record.encrypted_password THEN
        RAISE EXCEPTION 'La contraseña actual es incorrecta.';
    END IF;

    -- 4. Update to the new password
    UPDATE auth.users
    SET encrypted_password = crypt(p_new_password, gen_salt('bf'))
    WHERE id = current_user_id;

    -- 5. Return a success message
    RETURN json_build_object('success', TRUE, 'message', 'Contraseña actualizada correctamente.');

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Ocurrió un error inesperado: %', SQLERRM;
END;
$$;


ALTER FUNCTION "public"."update_user_password"("p_old_password" "text", "p_new_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_user_profile"("p_user_id" "uuid", "p_first_name" "text", "p_last_name" "text", "p_avatar_url" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    UPDATE auth.users
    SET
        raw_user_meta_data = jsonb_set(
            COALESCE(raw_user_meta_data, '{}'::jsonb),
            '{first_name}', to_jsonb(p_first_name),
            true
        ),
        raw_user_meta_data = jsonb_set(
            COALESCE(raw_user_meta_data, '{}'::jsonb),
            '{last_name}', to_jsonb(p_last_name),
            true
        ),
        raw_user_meta_data = jsonb_set(
            COALESCE(raw_user_meta_data, '{}'::jsonb),
            '{avatar_url}', to_jsonb(p_avatar_url),
            true
        )
    WHERE
        id = p_user_id;

    RETURN json_build_object('success', TRUE, 'message', 'Perfil actualizado correctamente.');

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Ocurrió un error inesperado: %', SQLERRM;
END;
$$;


