CREATE OR REPLACE FUNCTION "public"."upsert_integration_provider"("p_id" "uuid", "p_name" "text", "p_logo_url" "text", "p_country_id" "uuid", "p_category_id" "uuid", "p_status" "text", "p_endpoints" "jsonb", "p_config_schema" "jsonb", "p_api_schema" "jsonb") RETURNS SETOF "public"."integration_providers"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- La seguridad se maneja a nivel de RLS en la tabla integration_providers.
    -- Si el usuario no es superadmin, la política de INSERT/UPDATE fallará.
    RETURN QUERY
    INSERT INTO integration_providers (
        id, name, logo_url, country_id, category_id, status, endpoints, config_schema, api_schema
    )
    VALUES (
        COALESCE(p_id, gen_random_uuid()),
        p_name,
        p_logo_url,
        p_country_id,
        p_category_id,
        p_status,
        p_endpoints,
        p_config_schema,
        p_api_schema
    )
    ON CONFLICT (id) DO UPDATE SET
        name = p_name,
        logo_url = p_logo_url,
        country_id = p_country_id,
        category_id = p_category_id,
        status = p_status,
        endpoints = p_endpoints,
        config_schema = p_config_schema,
        api_schema = p_api_schema,
        updated_at = NOW()
    RETURNING *;
END;
$$;


ALTER FUNCTION "public"."upsert_integration_provider"("p_id" "uuid", "p_name" "text", "p_logo_url" "text", "p_country_id" "uuid", "p_category_id" "uuid", "p_status" "text", "p_endpoints" "jsonb", "p_config_schema" "jsonb", "p_api_schema" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_tenant_integration"("p_tenant_id" "uuid", "p_provider_slug" "text", "p_encrypted_credentials" "text", "p_nonce" "text", "p_environment" "text", "p_user_role" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Paso 1: Verificar explícitamente el permiso del usuario.
    IF p_user_role != 'super_admin' THEN
        RAISE EXCEPTION 'Acceso denegado. Se requiere rol de super_admin para gestionar integraciones.';
    END IF;

    -- Paso 2: Realizar la operación de escritura (INSERT o UPDATE).
    INSERT INTO public.tenant_integrations (
        tenant_id,
        provider,
        encrypted_credentials,
        nonce,
        environment
    )
    VALUES (
        p_tenant_id,
        p_provider_slug,
        p_encrypted_credentials,
        p_nonce,
        p_environment
    )
    ON CONFLICT (tenant_id, provider, environment)
    DO UPDATE SET
        encrypted_credentials = EXCLUDED.encrypted_credentials,
        nonce = EXCLUDED.nonce,
        updated_at = NOW();
END;
$$;


ALTER FUNCTION "public"."upsert_tenant_integration"("p_tenant_id" "uuid", "p_provider_slug" "text", "p_encrypted_credentials" "text", "p_nonce" "text", "p_environment" "text", "p_user_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_tenant_integration"("p_tenant_id" "uuid", "p_provider_slug" "text", "p_encrypted_credentials" "text", "p_nonce" "text", "p_environment" "text", "p_user_role" "text") IS 'Permite a un superadministrador guardar o actualizar las credenciales de una integración para un tenant específico.';



CREATE OR REPLACE FUNCTION "public"."url_encode"("data" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
    SELECT string_agg(
        CASE
            -- Caracteres no reservados que no necesitan codificación
            WHEN c ~ '^[a-zA-Z0-9._~-]$' THEN c
            -- Todos los demás caracteres se codifican en formato %XX
            ELSE '%' || upper(to_hex(ascii(c)))
        END, ''
    )
    FROM unnest(string_to_array(data, NULL)) AS c;
$_$;


ALTER FUNCTION "public"."url_encode"("data" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_user_role_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_role_name TEXT;
BEGIN
  -- Obtener el nombre del rol basado en el role_id
  SELECT name INTO v_role_name FROM public.roles WHERE id = NEW.role_id;

  -- Aplicar lógica de validación basada en el nombre del rol
  IF v_role_name = 'super_admin' THEN
    -- La única restricción para el super_admin es que no puede tener una sucursal (branch) asignada.
    -- Se elimina la restricción sobre tenant_id.
    IF NEW.branch_id IS NOT NULL THEN
      RAISE EXCEPTION 'Invalid assignment: super_admin cannot be associated with a specific branch.';
    END IF;
  ELSIF v_role_name = 'tenant_super_admin' THEN
    IF NEW.tenant_id IS NULL THEN
      RAISE EXCEPTION 'Invalid assignment: tenant_super_admin must have a tenant_id.';
    END IF;
    IF NEW.branch_id IS NOT NULL THEN
      RAISE EXCEPTION 'Invalid assignment: tenant_super_admin cannot be associated with a specific branch.';
    END IF;
  ELSIF v_role_name IN ('tenant_admin', 'tenant_user') THEN
    IF NEW.tenant_id IS NULL OR NEW.branch_id IS NULL THEN
      RAISE EXCEPTION 'Invalid assignment: tenant_admin and tenant_user roles must have both a tenant_id and a branch_id.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_user_role_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "schema_introspector"."get_all_constraints"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
    SELECT
        tc.constraint_name,
        tc.constraint_type,
        tc.table_schema,
        tc.table_name,
        kcu.column_name,
        ccu.table_schema AS foreign_table_schema,
        ccu.table_name AS foreign_table_name,
        ccu.column_name AS foreign_column_name
    FROM
        information_schema.table_constraints AS tc
    JOIN
        information_schema.key_column_usage AS kcu
        ON tc.constraint_name = kcu.constraint_name
        AND tc.table_schema = kcu.table_schema
    LEFT JOIN
        information_schema.constraint_column_usage AS ccu
        ON ccu.constraint_name = tc.constraint_name
        AND ccu.table_schema = tc.table_schema
    WHERE
        tc.table_schema IN ('public', 'storage', 'auth')
    ORDER BY
        tc.table_schema,
        tc.table_name,
        tc.constraint_name
  ) t;
$$;


ALTER FUNCTION "schema_introspector"."get_all_constraints"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "schema_introspector"."get_all_functions"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
    SELECT
        r.routine_schema,
        r.routine_name,
        r.data_type AS return_type,
        p.parameter_name,
        p.data_type AS parameter_type,
        p.parameter_mode,
        pg_get_functiondef(r.specific_name::regproc) AS function_definition
    FROM
        information_schema.routines r
    LEFT JOIN
        information_schema.parameters p ON r.specific_name = p.specific_name
    WHERE
        r.routine_schema IN ('public') -- Solo nos interesan las RPCs públicas
        AND r.routine_type = 'FUNCTION'
    ORDER BY
        r.routine_schema,
        r.routine_name,
        p.ordinal_position
  ) t;
$$;


ALTER FUNCTION "schema_introspector"."get_all_functions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "schema_introspector"."get_all_tables"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
    SELECT
        t.table_schema,
        t.table_name,
        c.column_name,
        c.ordinal_position,
        c.data_type,
        c.is_nullable,
        c.column_default
    FROM
        information_schema.tables t
    JOIN
        information_schema.columns c ON t.table_name = c.table_name AND t.table_schema = c.table_schema
    WHERE
        t.table_schema IN ('public', 'storage', 'auth')
        AND t.table_type = 'BASE TABLE'
    ORDER BY
        t.table_schema,
        t.table_name,
        c.ordinal_position
  ) t;
$$;


ALTER FUNCTION "schema_introspector"."get_all_tables"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "schema_introspector"."get_all_types"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
    SELECT
        t.typname AS enum_name,
        e.enumlabel AS enum_value,
        n.nspname AS enum_schema
    FROM
        pg_type t
    JOIN
        pg_enum e ON t.oid = e.enumtypid
    JOIN
        pg_catalog.pg_namespace n ON n.oid = t.typnamespace
    WHERE
        n.nspname IN ('public', 'storage', 'auth')
    ORDER BY
        n.nspname,
        t.typname,
        e.enumsortorder
  ) t;
$$;


ALTER FUNCTION "schema_introspector"."get_all_types"() OWNER TO "postgres";


