CREATE TABLE IF NOT EXISTS "public"."invoice_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "invoice_id" "uuid" NOT NULL,
    "product_id" "uuid",
    "subscription_plan_id" "uuid",
    "item_type" "text" NOT NULL,
    "description" "text" NOT NULL,
    "quantity" integer NOT NULL,
    "unit_price" numeric(12,2) NOT NULL,
    "total_price" numeric(12,2) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "service_id" "uuid",
    "parent_item_id" "uuid",
    CONSTRAINT "check_item_source_v2" CHECK (((("item_type" = 'PRODUCT'::"text") AND ("product_id" IS NOT NULL) AND ("service_id" IS NULL)) OR (("item_type" = 'SERVICE'::"text") AND ("service_id" IS NOT NULL) AND ("product_id" IS NULL)) OR (("item_type" = 'COMBO'::"text") AND ("product_id" IS NULL) AND ("service_id" IS NULL)) OR (("item_type" = 'CUSTOM'::"text") AND ("product_id" IS NULL) AND ("service_id" IS NULL)) OR (("item_type" = 'SUBSCRIPTION_PLAN'::"text") AND ("subscription_plan_id" IS NOT NULL) AND ("product_id" IS NULL) AND ("service_id" IS NULL))))
);


ALTER TABLE "public"."invoice_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."invoice_items" IS 'Items polimórficos de una factura (productos o suscripciones).';



COMMENT ON COLUMN "public"."invoice_items"."item_type" IS 'Tipo de item: PRODUCT o SUBSCRIPTION_PLAN.';



COMMENT ON CONSTRAINT "check_item_source_v2" ON "public"."invoice_items" IS 'Validates that an invoice item has a valid type and corresponding ID. PRODUCT requires product_id, SERVICE requires service_id. COMBO and CUSTOM are for grouping or manual entries. SUBSCRIPTION_PLAN is for tenant billing.';



