CREATE TABLE IF NOT EXISTS "public"."units_of_measure" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid",
    "name" "text" NOT NULL,
    "abbreviation" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."units_of_measure" OWNER TO "postgres";


COMMENT ON TABLE "public"."units_of_measure" IS 'Stores units of measure for products, can be tenant-specific or global (null tenant_id).';



CREATE TABLE IF NOT EXISTS "public"."user_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "branch_id" "uuid",
    "user_id" "uuid" NOT NULL,
    "role_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "default_product_commission_rate" numeric(5,2) DEFAULT 0.00 NOT NULL,
    "default_service_commission_rate" numeric(5,2) DEFAULT 0.00 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "base_salary" numeric(10,2) DEFAULT 0.00 NOT NULL,
    "is_schedulable" boolean DEFAULT true NOT NULL
);


ALTER TABLE "public"."user_assignments" OWNER TO "postgres";


COMMENT ON COLUMN "public"."user_assignments"."status" IS 'The status of the user assignment (e.g., active, inactive)';



COMMENT ON COLUMN "public"."user_assignments"."default_product_commission_rate" IS 'Default commission rate for product sales for this user in this branch.';



COMMENT ON COLUMN "public"."user_assignments"."default_service_commission_rate" IS 'Default commission rate for services for this user in this branch.';



COMMENT ON COLUMN "public"."user_assignments"."base_salary" IS 'Salario base mensual del usuario para esta asignación específica.';



