CREATE POLICY "Allow access to items of own combos" ON "public"."combo_items" USING ((EXISTS ( SELECT 1
   FROM "public"."combos"
  WHERE (("combos"."id" = "combo_items"."combo_id") AND "public"."tenant_only_rls_policy"("combos"."tenant_id"))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."combos"
  WHERE (("combos"."id" = "combo_items"."combo_id") AND "public"."tenant_only_rls_policy"("combos"."tenant_id")))));



CREATE POLICY "Allow access to own branch combo assignments" ON "public"."branch_combos" USING ("public"."tenant_only_rls_policy"("tenant_id")) WITH CHECK ("public"."tenant_only_rls_policy"("tenant_id"));



CREATE POLICY "Allow access to own branch combo item prices" ON "public"."branch_combo_item_prices" USING ("public"."tenant_only_rls_policy"("tenant_id")) WITH CHECK ("public"."tenant_only_rls_policy"("tenant_id"));



CREATE POLICY "Allow all for authenticated users" ON "public"."contact_types" TO "authenticated" USING (("tenant_id" = ( SELECT ("current_setting"('''app.tenant_id'''::"text", true))::"uuid" AS "current_setting"))) WITH CHECK (("tenant_id" = ( SELECT ("current_setting"('''app.tenant_id'''::"text", true))::"uuid" AS "current_setting")));



CREATE POLICY "Allow all for authenticated users" ON "public"."rescheduled_attentions" USING (("auth"."role"() = 'authenticated'::"text")) WITH CHECK (("auth"."role"() = 'authenticated'::"text"));



CREATE POLICY "Allow all for super_admin on phone_prefixes" ON "public"."phone_prefixes" USING ((("auth"."jwt"() ->> 'role'::"text") = 'super_admin'::"text")) WITH CHECK ((("auth"."jwt"() ->> 'role'::"text") = 'super_admin'::"text"));



CREATE POLICY "Allow delete access to users of the same tenant" ON "public"."product_images" FOR DELETE USING (("tenant_id" = (( SELECT ((("auth"."jwt"() ->> 'app_metadata'::"text"))::"jsonb" ->> 'tenant_id'::"text")))::"uuid"));



CREATE POLICY "Allow full access for tenant admins" ON "public"."treatment_categories" USING (("auth"."uid"() IN ( SELECT "ua"."user_id"
   FROM ("public"."user_assignments" "ua"
     JOIN "public"."roles" "r" ON (("ua"."role_id" = "r"."id")))
  WHERE (("ua"."tenant_id" = "treatment_categories"."tenant_id") AND (("r"."name" = 'tenant_admin'::"text") OR ("r"."name" = 'tenant_super_admin'::"text")))))) WITH CHECK (("auth"."uid"() IN ( SELECT "ua"."user_id"
   FROM ("public"."user_assignments" "ua"
