CREATE POLICY "Universe Branches Access Control" ON "public"."branches" USING (((EXISTS ( SELECT 1
   FROM "jsonb_array_elements"((("auth"."jwt"() -> 'app_metadata'::"text") -> 'assignments'::"text")) "elem"("value")
  WHERE (("elem"."value" ->> 'role'::"text") = 'super_admin'::"text"))) OR (EXISTS ( SELECT 1
   FROM "jsonb_array_elements"((("auth"."jwt"() -> 'app_metadata'::"text") -> 'assignments'::"text")) "elem"("value")
  WHERE ((("elem"."value" ->> 'tenant_id'::"text"))::"uuid" = "branches"."tenant_id"))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "jsonb_array_elements"((("auth"."jwt"() -> 'app_metadata'::"text") -> 'assignments'::"text")) "elem"("value")
  WHERE ((("elem"."value" ->> 'role'::"text") = 'super_admin'::"text") OR (((("elem"."value" ->> 'tenant_id'::"text"))::"uuid" = "branches"."tenant_id") AND (("elem"."value" ->> 'role'::"text") = ANY (ARRAY['tenant_super_admin'::"text", 'tenant_admin'::"text"])))))));



CREATE POLICY "Universe Tenant Access Control" ON "public"."tenants" USING (((EXISTS ( SELECT 1
   FROM "jsonb_array_elements"((("auth"."jwt"() -> 'app_metadata'::"text") -> 'assignments'::"text")) "elem"("value")
  WHERE (("elem"."value" ->> 'role'::"text") = 'super_admin'::"text"))) OR (EXISTS ( SELECT 1
   FROM "jsonb_array_elements"((("auth"."jwt"() -> 'app_metadata'::"text") -> 'assignments'::"text")) "elem"("value")
  WHERE ((("elem"."value" ->> 'tenant_id'::"text"))::"uuid" = "tenants"."id"))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "jsonb_array_elements"((("auth"."jwt"() -> 'app_metadata'::"text") -> 'assignments'::"text")) "elem"("value")
  WHERE (("elem"."value" ->> 'role'::"text") = 'super_admin'::"text"))));



