CREATE POLICY "Users can insert attachments for their own comments" ON "public"."chatter_attachments" FOR INSERT WITH CHECK (("user_id" = "auth"."uid"()));



CREATE POLICY "Users can view attachments in their own tenant" ON "public"."chatter_attachments" FOR SELECT USING (("tenant_id" IN ( SELECT "user_assignments"."tenant_id"
   FROM "public"."user_assignments"
  WHERE ("user_assignments"."user_id" = "auth"."uid"()))));



